                                    .weight(1f)
                                    .background(if (isSel) Color(0xFF1565C0) else Color(0xFFF3F4F6), RoundedCornerShape(6.dp))
                                    .clickable { paymentMethodInput = m }
                                    .padding(vertical = 6.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = m,
                                    color = if (isSel) Color.White else DarkText,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 10.sp
                                )
                            }
                        }
                    }

                    val targetNum = when (paymentMethodInput) {
                        "Nagad" -> currentNagad
                        "Rocket" -> currentRocket
                        "Google Pay" -> currentGooglePay
                        "Wise" -> currentWise
                        else -> currentBkash
                    }

                    val targetInst = when (paymentMethodInput) {
                        "Nagad" -> currentNagadInst
                        "Rocket" -> currentRocketInst
                        "Google Pay" -> currentGooglePlayInst
                        "Wise" -> currentWiseInst
                        else -> currentBkashInst
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 8.dp)
                            .background(Color(0xFFFFF3E0), RoundedCornerShape(8.dp))
                            .border(1.dp, Color(0xFFFFB74D), RoundedCornerShape(8.dp))
                            .padding(8.dp)
                    ) {
                        Text(
                            text = if (language == AppLanguage.BAN)
                                "অফিশিয়াল $paymentMethodInput নম্বর/আইডি: ${targetNum.ifBlank { "01700000000" }}"
                            else "Official $paymentMethodInput Number/ID: ${targetNum.ifBlank { "01700000000" }}",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFFE65100)
                        )
                        if (targetInst.isNotBlank()) {
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = targetInst,
                                fontSize = 11.sp,
                                color = Color(0xFF5D4037)
                            )
                        }
                    }

                    OutlinedTextField(
                        value = senderPhoneInput,
                        onValueChange = { senderPhoneInput = it },
                        label = { Text(if (language == AppLanguage.BAN) "আপনার পেমেন্ট নম্বর / ইমেইল" else "Sender Phone Number / Email") },
                        modifier = Modifier.fillMaxWidth().padding(bottom = 6.dp)
                    )

                    val isGpayAd = paymentMethodInput == "Google Pay"
                    if (!isGpayAd) {
                        OutlinedTextField(
                            value = paymentTxnIdInput,
                            onValueChange = { paymentTxnIdInput = it },
                            label = { Text(if (language == AppLanguage.BAN) "ট্রানজেকশন আইডি (TxnID) *" else "Transaction ID (TxnID) *") },
                            placeholder = { Text("TRX123456") },
                            modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp)
                        )
                    }

                    // REAL-TIME LIVE ADS & VIDEO PERFORMANCE TRACKER DASHBOARD
                    if (advertiserCompanyAds.isNotEmpty()) {
                        Divider(color = Color(0xFFEEEEEE), modifier = Modifier.padding(vertical = 10.dp))

                        Text(
                            text = if (language == AppLanguage.BAN) "📊 আমার কোম্পানির লাইভ বিজ্ঞাপন ও ট্র্যাকিং ড্যাশবোর্ড" else "📊 Live Ads & Performance Tracking Dashboard",
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.sp,
                            color = Color(0xFF1565C0),
                            modifier = Modifier.padding(bottom = 8.dp)
                        )

                        advertiserCompanyAds.forEach { ad ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(bottom = 8.dp),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFF8F9FA)),
                                border = BorderStroke(1.dp, Color(0xFFE0E0E0)),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Column(modifier = Modifier.padding(10.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Surface(
                                                color = if (ad.isVideo) Color(0xFFFFF3E0) else Color(0xFFE3F2FD),
                                                shape = RoundedCornerShape(4.dp)
                                            ) {
                                                Text(
                                                    text = if (ad.isVideo) "🎬 VIDEO AD" else "📷 PHOTO BANNER",
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (ad.isVideo) Color(0xFFE65100) else Color(0xFF1565C0),
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                text = ad.title,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                color = DarkText,
                                                maxLines = 1
                                            )
                                        }

                                        Surface(
                                            color = Color(0xFFE8F5E9),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(6.dp)
                                                        .background(Color(0xFF2E7D32), CircleShape)
                                                )
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text(
                                                    text = if (language == AppLanguage.BAN) "🟢 লাইভ চালু আছে" else "🟢 LIVE",
                                                    fontSize = 9.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color(0xFF2E7D32)
                                                )
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(8.dp))

                                    // Real-Time Metrics Cards Grid
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        // Total Views Card
                                        Surface(
                                            color = Color.White,
                                            shape = RoundedCornerShape(6.dp),
                                            border = BorderStroke(1.dp, Color(0xFFE0E0E0)),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(6.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally
                                            ) {
                                                Text(if (language == AppLanguage.BAN) "👁️ ভিউ সংখ্যা" else "👁️ Views", fontSize = 9.sp, color = SecondaryText)
                                                Text("${ad.viewsCount}", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1565C0))
                                            }
                                        }

                                        // Total Clicks Card
                                        Surface(
                                            color = Color.White,
                                            shape = RoundedCornerShape(6.dp),
                                            border = BorderStroke(1.dp, Color(0xFFE0E0E0)),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Column(
                                                modifier = Modifier.padding(6.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally
                                            ) {
                                                Text(if (language == AppLanguage.BAN) "🖱️ ক্লিক সংখ্যা" else "🖱️ Clicks", fontSize = 9.sp, color = SecondaryText)
                                                Text("${ad.clicksCount}", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = Color(0xFF2E7D32))
                                            }
                                        }

                                        // CTR Card
                                        Surface(
                                            color = Color.White,
                                            shape = RoundedCornerShape(6.dp),
                                            border = BorderStroke(1.dp, Color(0xFFE0E0E0)),
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            val ctrStr = if (ad.viewsCount > 0) String.format("%.1f", (ad.clicksCount.toDouble() / ad.viewsCount) * 100) else "0.0"
                                            Column(
                                                modifier = Modifier.padding(6.dp),
                                                horizontalAlignment = Alignment.CenterHorizontally
                                            ) {
                                                Text(if (language == AppLanguage.BAN) "🎯 CTR %" else "🎯 CTR %", fontSize = 9.sp, color = SecondaryText)
                                                Text("$ctrStr%", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = Color(0xFFE65100))
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(6.dp))

                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = if (language == AppLanguage.BAN) "প্ল্যান: ${ad.planType} • মেয়াদ: ${ad.expiryDate}" else "Plan: ${ad.planType} • Expiry: ${ad.expiryDate}",
                                            fontSize = 9.sp,
                                            color = SecondaryText
                                        )
                                        Text(
                                            text = if (ad.targetUrl.length > 25) ad.targetUrl.take(25) + "..." else ad.targetUrl,
                                            fontSize = 9.sp,
                                            color = Color(0xFF1E88E5),
                                            fontWeight = FontWeight.SemiBold
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        confirmButton = {
            if (currentAdvertiser != null) {
                Button(
                    onClick = {
                        if (adTitleInput.isBlank()) {
                            android.widget.Toast.makeText(context, if (language == AppLanguage.BAN) "বিজ্ঞাপনের শিরোনাম দিন" else "Please enter ad title", android.widget.Toast.LENGTH_SHORT).show()
                            return@Button
                        }

                        val comp = currentAdvertiser!!
                        val compId = comp.id
                        val compName = comp.companyName

                        viewModel.addCompanyBannerSubscription(
                            context = context,
                            companyId = compId,
                            companyName = compName,
                            planType = selectedPlanType,
                            adTitle = adTitleInput,
                            bannerMediaUrl = bannerMediaUrlInput.ifBlank { "https://images.unsplash.com/photo-1542744094-3a31f103e35f?auto=format&fit=crop&w=600&q=80" },
                            isVideo = isVideoAd,
                            targetUrl = targetUrlInput.ifBlank { "https://google.com" },
                            paymentMethod = paymentMethodInput,
                            transactionId = paymentTxnIdInput.ifBlank { "TXN_" + System.currentTimeMillis() }
                        )

                        android.widget.Toast.makeText(
                            context,
                            if (language == AppLanguage.BAN) "আপনার বিজ্ঞাপন সফলভাবে জমা ও প্রকাশ করা হয়েছে!" else "Ad submitted & published successfully!",
                            android.widget.Toast.LENGTH_LONG
                        ).show()
                        onDismiss()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32))
                ) {
                    Icon(Icons.Default.CheckCircle, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = if (language == AppLanguage.BAN) "পেমেন্ট জমা দিন & বিজ্ঞাপন লাইভ করুন" else "Submit Payment & Publish Ad",
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(if (language == AppLanguage.BAN) "বন্ধ করুন" else "Close")
            }
        }
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CommonTopAppBar(
    title: String,
    currentLang: AppLanguage,
    onLangToggle: () -> Unit,
    onBack: () -> Unit,
    showBack: Boolean,
    userSession: BloodDonor?,
    onProfileClick: () -> Unit,
    onSearchClick: () -> Unit,
    onMenuClick: (() -> Unit)? = null,
    viewModel: MainViewModel? = null
) {
    var showSubscriptionDialog by remember { mutableStateOf(false) }

    if (showSubscriptionDialog && viewModel != null) {
        VideoAdvertiserPortalDialog(
            viewModel = viewModel,
            language = currentLang,
            onDismiss = { showSubscriptionDialog = false }
        )
    }

    TopAppBar(
        title = {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(
                    imageVector = Icons.Filled.Bloodtype,
                    contentDescription = "Blood Drop",
                    tint = BloodRed,
                    modifier = Modifier.size(28.dp)
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleLarge.copy(
                        fontWeight = FontWeight.Bold,
                        color = BloodRed,
                        letterSpacing = 0.5.sp
                    ),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        },
        navigationIcon = {
            if (showBack) {
                IconButton(onClick = onBack, modifier = Modifier.testTag("app_bar_back")) {
                    Icon(
                        imageVector = Icons.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = DarkText
                    )
                }
            } else if (onMenuClick != null) {
                IconButton(onClick = onMenuClick, modifier = Modifier.testTag("app_bar_menu")) {
                    Icon(
                        imageVector = Icons.Filled.Menu,
                        contentDescription = "Menu",
                        tint = DarkText
                    )
                }
            }
        },
        actions = {
            // Search button added to top bar
            IconButton(onClick = onSearchClick) {
                Icon(
                    imageVector = Icons.Filled.Search,
                    contentDescription = "Search",
                    tint = BloodRed
                )
            }

            // Language Selector button (Toggle instantly between ENG & BAN)
            Button(
                onClick = onLangToggle,
                colors = ButtonDefaults.buttonColors(
                    containerColor = LightPinkRed,
                    contentColor = DarkBloodRed
                ),
                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                shape = RoundedCornerShape(16.dp),
                modifier = Modifier
                    .padding(end = 8.dp)
                    .testTag("lang_toggle_btn")
            ) {
                Icon(
                    imageVector = Icons.Outlined.Translate,
                    contentDescription = "Translate",
                    modifier = Modifier.size(16.dp)
                )
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (currentLang == AppLanguage.ENG) "বাংলা" else "ENG",
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp
                )
            }

            // Video Ads & Advertiser Portal Button (Top Bar Paper Plane / Video Icon)
            if (viewModel != null) {
                Surface(
                    shape = RoundedCornerShape(20.dp),
                    color = Color.Transparent,
                    border = BorderStroke(1.dp, Color(0xFFFFD700)),
                    modifier = Modifier
                        .padding(end = 8.dp)
                        .background(
                            brush = androidx.compose.ui.graphics.Brush.horizontalGradient(
                                colors = listOf(Color(0xFF0D47A1), Color(0xFF1976D2))
                            ),
                            shape = RoundedCornerShape(20.dp)
                        )
                        .clickable { showSubscriptionDialog = true }
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.padding(horizontal = 9.dp, vertical = 5.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Videocam,
                            contentDescription = "Video Ads Portal",
                            tint = Color(0xFFFFD700),
                            modifier = Modifier.size(16.dp)
                        )
                        Spacer(modifier = Modifier.width(4.dp))
                        Text(
                            text = if (currentLang == AppLanguage.ENG) "Video Ads" else "ভিডিও অ্যাড",
                            color = Color.White,
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp
                        )
                    }
                }
            }

            if (userSession != null) {
                Box(
                    modifier = Modifier
                        .padding(end = 12.dp)
                        .size(36.dp)
                        .clip(CircleShape)
                        .background(BloodRed)
                        .clickable { onProfileClick() }
                        .testTag("app_bar_profile_active"),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = userSession.bloodGroup,
                        color = Color.White,
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            } else {
                IconButton(
                    onClick = onProfileClick,
                    modifier = Modifier
                        .padding(end = 8.dp)
                        .testTag("app_bar_profile_guest")
                ) {
                    Icon(
                        imageVector = Icons.Filled.AccountCircle,
                        contentDescription = "Sign In",
                        tint = BloodRed,
                        modifier = Modifier.size(32.dp)
                    )
                }
            }
        },
        colors = TopAppBarDefaults.topAppBarColors(
            containerColor = Color.White,
            scrolledContainerColor = Color.White
        ),
        modifier = Modifier.shadow(4.dp)
    )
}

@Composable
fun ScrollableDrawerItems(
    strings: Map<String, String>,
    currentLanguage: AppLanguage,
    currentScreen: AppScreen,
    userSession: BloodDonor?,
    unreadChatCount: Int = 0,
    onItemClick: (AppScreen) -> Unit,
    onLanguageToggle: () -> Unit,
    onLogout: () -> Unit,
    isAdmin: Boolean
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 12.dp, vertical = 8.dp)
    ) {
        val activeColor = LightPinkRed
        val activeContentColor = DarkBloodRed
        val isBn = currentLanguage == AppLanguage.BAN
        
        // Role Determination
        val userRole = userSession?.role?.ifBlank { "Donor" } ?: "Guest"
        val isDonor = userSession != null && (userRole.equals("Donor", ignoreCase = true) || userRole.equals("User", ignoreCase = true))
        val isRequester = userSession != null && (userRole.equals("Requester", ignoreCase = true) || userRole.equals("Recipient", ignoreCase = true) || userRole.equals("Patient", ignoreCase = true))
        val isHospital = userSession != null && userRole.equals("Hospital", ignoreCase = true)
        val isDoctor = userSession != null && userRole.equals("Doctor", ignoreCase = true)
        val isAmbulance = userSession != null && userRole.equals("Ambulance", ignoreCase = true)
        val isGuest = userSession == null

        // Helper lambda for drawer item
        val drawerItem = @Composable { label: String, icon: ImageVector, screen: AppScreen, tag: String, badgeCount: Int ->
            val isSelected = currentScreen == screen
            NavigationDrawerItem(
                label = { Text(text = label, fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal) },
                icon = {
                    if (badgeCount > 0) {
                        BadgedBox(
                            badge = {
                                Badge(
                                    containerColor = BloodRed,
                                    contentColor = Color.White
                                ) {
                                    Text(
                                        text = if (badgeCount > 99) "99+" else badgeCount.toString(),
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }
                        ) {
                            Icon(imageVector = icon, contentDescription = label)
                        }
                    } else {
                        Icon(imageVector = icon, contentDescription = label)
                    }
                },
                selected = isSelected,
                onClick = { onItemClick(screen) },
                colors = NavigationDrawerItemDefaults.colors(
                    selectedContainerColor = activeColor,
                    selectedIconColor = activeContentColor,
                    selectedTextColor = activeContentColor,
                    unselectedContainerColor = Color.Transparent,
                    unselectedIconColor = SecondaryText,
                    unselectedTextColor = DarkText
                ),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier
                    .padding(vertical = 4.dp)
                    .testTag(tag)
            )
        }

        // 1. Home (All Roles)
        drawerItem(
            strings["btn_nav_home"] ?: "Home",
            Icons.Filled.Home,
            AppScreen.HOME,
            "drawer_home",
            0
        )

        // 2. DONOR ROLE SPECIFIC MENU
        if (isDonor) {
            drawerItem(
                if (isBn) "🚨 জরুরি রক্তের চাহিদা" else "Urgent Needs (To Donate)",
                Icons.Filled.CrisisAlert,
                AppScreen.EMERGENCY_REQUESTS,
                "drawer_emergency",
                0
            )
            drawerItem(
                if (isBn) "🔍 ডোনার সহকর্মী খুঁজুন" else "Search Fellow Donors",
                Icons.Filled.Search,
                AppScreen.SEARCH_DONOR,
                "drawer_search",
                0
            )
            drawerItem(
                if (isBn) "🚩 রক্তদাতা ভলান্টিয়ার টিম" else "Volunteer Donor Teams",
                Icons.Filled.Groups,
                AppScreen.DONOR_TEAMS,
                "drawer_donor_teams",
                0
            )
        }

        // 3. REQUESTER / PATIENT ROLE SPECIFIC MENU
        if (isRequester) {
            drawerItem(
                if (isBn) "➕ রক্তের আবেদন করুন" else "Post Blood Request",
                Icons.Filled.AddCircle,
                AppScreen.REQUEST_BLOOD,
                "drawer_request",
                0
            )
            drawerItem(
                if (isBn) "🔍 রক্তদাতা অনুসন্ধান" else "Find Donors",
                Icons.Filled.Search,
                AppScreen.SEARCH_DONOR,
                "drawer_search",
                0
            )
            drawerItem(
                if (isBn) "🚨 জরুরি রক্তের আবেদনসমূহ" else "Urgent Emergency Requests",
                Icons.Filled.CrisisAlert,
                AppScreen.EMERGENCY_REQUESTS,
                "drawer_emergency",
                0
            )
            drawerItem(
                if (isBn) "🏥 হাসপাতাল ডিরেক্টরি" else "Hospital Directory",
                Icons.Filled.Apartment,
                AppScreen.HOSPITAL_DIRECTORY,
                "drawer_hospital",
                0
            )
            drawerItem(
                if (isBn) "👨‍⚕️ ডাক্তার পয়েন্টমেন্ট" else "Doctor Directory",
                Icons.Filled.Healing,
                AppScreen.DOCTOR_DIRECTORY,
                "drawer_doctor",
                0
            )
            drawerItem(
                if (isBn) "🚑 জরুরি অ্যাম্বুলেন্স" else "Ambulance Service",
                Icons.Filled.AirportShuttle,
                AppScreen.AMBULANCE_LIST,
                "drawer_ambulance",
                0
            )
        }

        // 4. HOSPITAL ROLE SPECIFIC MENU
        if (isHospital) {
            drawerItem(
                if (isBn) "🏥 হাসপাতাল ডিরেক্টরি ও কেয়ার" else "Hospital Care Directory",
                Icons.Filled.Apartment,
                AppScreen.HOSPITAL_DIRECTORY,
                "drawer_hospital",
                0
            )
            drawerItem(
                if (isBn) "👨‍⚕️ নিয়োজিত ডাক্তারসমূহ" else "Hospital Doctors",
                Icons.Filled.Healing,
                AppScreen.DOCTOR_DIRECTORY,
                "drawer_doctor",
                0
            )
            drawerItem(
                if (isBn) "🚑 জরুরি অ্যাম্বুলেন্স সার্ভিস" else "Ambulance Service",
                Icons.Filled.AirportShuttle,
                AppScreen.AMBULANCE_LIST,
                "drawer_ambulance",
                0
            )
            drawerItem(
                if (isBn) "🚨 হাসপাতালে জরুরি রক্তের চাহিদা" else "Hospital Blood Needs",
                Icons.Filled.CrisisAlert,
                AppScreen.EMERGENCY_REQUESTS,
                "drawer_emergency",
                0
            )
        }

        // 5. DOCTOR ROLE SPECIFIC MENU
        if (isDoctor) {
            drawerItem(
                if (isBn) "👨‍⚕️ ডাক্তার ডিরেক্টরি ও সিরিয়াল" else "Doctor Appointments",
                Icons.Filled.Healing,
                AppScreen.DOCTOR_DIRECTORY,
                "drawer_doctor",
                0
            )
            drawerItem(
                if (isBn) "🏥 সংযুক্ত হাসপাতাল" else "Associated Hospitals",
                Icons.Filled.Apartment,
                AppScreen.HOSPITAL_DIRECTORY,
                "drawer_hospital",
                0
            )
        }

        // 6. AMBULANCE ROLE SPECIFIC MENU
        if (isAmbulance) {
            drawerItem(
                if (isBn) "🚑 অ্যাম্বুলেন্স ড্রাইভার ড্যাশবোর্ড" else "Ambulance Dashboard",
                Icons.Filled.Dashboard,
                AppScreen.AMBULANCE_DASHBOARD,
                "drawer_ambulance_dashboard",
                0
            )
            drawerItem(
                if (isBn) "🚑 বুকিং তালিকা ও গাড়ি সার্ভিস" else "Ambulance List",
                Icons.Filled.AirportShuttle,
                AppScreen.AMBULANCE_LIST,
                "drawer_ambulance",
                0
            )
        }

        // 7. GUEST MENU
        if (isGuest) {
            drawerItem(
                strings["card_search_donor"] ?: "Search Donor",
                Icons.Filled.Search,
                AppScreen.SEARCH_DONOR,
                "drawer_search",
                0
            )
            drawerItem(
                strings["card_request_blood"] ?: "Request Blood",
                Icons.Filled.AddCircle,
                AppScreen.REQUEST_BLOOD,
                "drawer_request",
                0
            )
            drawerItem(
                strings["card_emergency_req"] ?: "Emergency Requests",
                Icons.Filled.LocalHospital,
                AppScreen.EMERGENCY_REQUESTS,
                "drawer_emergency",
                0
            )
            drawerItem(
                if (isBn) "🏥 হাসপাতালসমূহ" else "Hospitals",
                Icons.Filled.Apartment,
                AppScreen.HOSPITAL_DIRECTORY,
                "drawer_hospital",
                0
            )
            drawerItem(
                if (isBn) "👨‍⚕️ ডাক্তারবৃন্দ" else "Doctors",
                Icons.Filled.Healing,
                AppScreen.DOCTOR_DIRECTORY,
                "drawer_doctor",
                0
            )
            drawerItem(
                strings["card_ambulance"] ?: "Ambulance Service",
                Icons.Filled.AirportShuttle,
                AppScreen.AMBULANCE_LIST,
                "drawer_ambulance",
                0
            )
            drawerItem(
                if (isBn) "রক্তদাতা স্বেচ্ছাসেবক টিম" else "Volunteer Donor Teams",
                Icons.Filled.Groups,
                AppScreen.DONOR_TEAMS,
                "drawer_donor_teams",
                0
            )
        }

        // Common for all authenticated users
        if (!isGuest) {
            drawerItem(
                strings["chat_title"] ?: "Chat & Messaging",
                Icons.Filled.Forum,
                AppScreen.CHAT_INBOX,
                "drawer_chat_inbox",
                unreadChatCount
            )
            drawerItem(
                strings["notification_title"] ?: "Notifications",
                Icons.Filled.Notifications,
                AppScreen.NOTIFICATIONS,
                "drawer_notifications",
                0
            )
        }

        // Support Chat
        drawerItem(
            strings["support_chat"] ?: "Live Support Chat",
            Icons.Filled.HeadsetMic,
            AppScreen.SUPPORT_CHAT,
            "drawer_support_chat",
            0
        )

        // Admin Panel (Only if Admin)
        if (isAdmin || userRole.equals("Admin", ignoreCase = true)) {
            HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp), color = LightBorder)
            Text(
                text = if (isBn) "এডমিন প্যানেল" else "Admin Panel",
                style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold, color = SecondaryText),
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
            )
            drawerItem(
                strings["dashboard_title"] ?: "Admin Dashboard",
                Icons.Filled.Security,
                AppScreen.ADMIN_DASHBOARD,
                "drawer_admin",
                0
            )
        }

        HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp), color = LightBorder)
        Text(
            text = if (isBn) "সেটিংস" else "Settings",
            style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold, color = SecondaryText),
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
        )

        // Language Select
        NavigationDrawerItem(
            label = { 
                Text(
                    text = if (isBn) "English (ভাষা পরিবর্তন)" else "বাংলা (Switch Language)",
                    fontWeight = FontWeight.Normal
                ) 
            },
            icon = { Icon(imageVector = Icons.Filled.Translate, contentDescription = "Language") },
            selected = false,
            onClick = onLanguageToggle,
            colors = NavigationDrawerItemDefaults.colors(
                unselectedContainerColor = Color.Transparent,
                unselectedIconColor = SecondaryText,
                unselectedTextColor = DarkText
            ),
            shape = RoundedCornerShape(12.dp),
            modifier = Modifier
                .padding(vertical = 4.dp)
                .testTag("drawer_language")
        )

        // Profile / Login / Logout
        if (userSession != null) {
            val profileTitle = when {
                isDonor -> if (isBn) "আমার ডোনার প্রোফাইল" else "My Donor Profile"
                isRequester -> if (isBn) "আমার রক্তগ্রহীতা প্রোফাইল" else "My Patient Profile"
                isHospital -> if (isBn) "আমার হাসপাতাল প্রোফাইল" else "My Hospital Profile"
                isDoctor -> if (isBn) "আমার ডাক্তার প্রোফাইল" else "My Doctor Profile"
                isAmbulance -> if (isBn) "আমার অ্যাম্বুলেন্স অ্যাকাউন্ট" else "My Ambulance Profile"
                else -> strings["user_profile_title"] ?: "My Profile"
            }
            drawerItem(
                profileTitle,
                Icons.Filled.Person,
                AppScreen.USER_PROFILE,
                "drawer_profile",
                0
            )

            NavigationDrawerItem(
                label = { Text(text = strings["logout"] ?: "Log Out", fontWeight = FontWeight.Normal) },
                icon = { Icon(imageVector = Icons.Filled.ExitToApp, contentDescription = "Log Out") },
                selected = false,
                onClick = onLogout,
                colors = NavigationDrawerItemDefaults.colors(
                    unselectedContainerColor = Color.Transparent,
                    unselectedIconColor = BloodRed,
                    unselectedTextColor = BloodRed
                ),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier
                    .padding(vertical = 4.dp)
                    .testTag("drawer_logout")
            )
        } else {
            NavigationDrawerItem(
                label = { Text(text = strings["login_title"] ?: "Sign In", fontWeight = FontWeight.Normal) },
                icon = { Icon(imageVector = Icons.Filled.Login, contentDescription = "Login") },
                selected = false,
                onClick = { onItemClick(AppScreen.LOGIN_REGISTER) },
                colors = NavigationDrawerItemDefaults.colors(
                    unselectedContainerColor = Color.Transparent,
                    unselectedIconColor = SecondaryText,
                    unselectedTextColor = DarkText
                ),
                shape = RoundedCornerShape(12.dp),
                modifier = Modifier
                    .padding(vertical = 4.dp)
                    .testTag("drawer_login")
            )
        }
    }
}

@Composable
fun CommonBottomNavigationBar(
    currentScreen: AppScreen,
    onNavigate: (AppScreen) -> Unit,
    isAdmin: Boolean,
    strings: Map<String, String>,
    unreadChatCount: Int = 0
) {
    NavigationBar(
        containerColor = Color.White,
        tonalElevation = 8.dp,
        modifier = Modifier.shadow(12.dp)
    ) {
        NavigationBarItem(
            selected = currentScreen == AppScreen.HOME,
            onClick = { onNavigate(AppScreen.HOME) },
            icon = { Icon(Icons.Filled.Home, contentDescription = "Home") },
            label = { Text(strings["btn_nav_home"] ?: "Home", fontSize = 10.sp, fontWeight = FontWeight.Medium) },
            colors = NavigationBarItemDefaults.colors(
                selectedIconColor = BloodRed,
                selectedTextColor = BloodRed,
                indicatorColor = LightPinkRed
            ),
            modifier = Modifier.testTag("nav_home")
