                            }
                            DropdownMenuItem(
                                text = { Text("$flag $ctyName", fontSize = 14.sp) },
                                onClick = {
                                    regCountryInput = ctyName
                                    if (ctyName != "Bangladesh") {
                                        regDistrictInput = ""
                                        regUpazilaInput = ""
                                    } else {
                                        regDistrictInput = "Dhaka"
                                        regUpazilaInput = "Mirpur"
                                    }
                                    expandedCountry = false
                                }
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                if (regRoleInput == "Donor") {
                    OutlinedTextField(
                        value = regLastDonationInput,
                        onValueChange = { regLastDonationInput = it },
                        label = { Text(strings["last_donation_label"] ?: "Last Donation Date") },
                        placeholder = { Text(strings["last_donation_placeholder"] ?: "e.g. 2026-03-10 or Never") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("reg_last_donation_input"),
                        shape = RoundedCornerShape(12.dp),
                        leadingIcon = { Icon(Icons.Filled.CalendarMonth, contentDescription = "Calendar") }
                    )

                    Spacer(modifier = Modifier.height(24.dp))
                } else {
                    Spacer(modifier = Modifier.height(12.dp))
                }
            }

            // REGISTRATION POLICY CHECKBOX & LINK
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 6.dp),
                colors = CardDefaults.cardColors(containerColor = LightPinkRed.copy(alpha = 0.35f)),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.dp, BloodRed.copy(alpha = 0.3f))
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 8.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val (policyTitle, policyThemeColor) = when (regAccountType) {
                        "Doctor" -> Pair(
                            if (language == AppLanguage.BAN) "ডাক্তার রেজিস্ট্রেশন নীতি ও শর্তাবলীতে" else "Doctor Registration Terms & Policy",
                            Color(0xFF8E24AA)
                        )
                        "Hospital" -> Pair(
                            if (language == AppLanguage.BAN) "হাসপাতাল লিস্টিং নীতি ও শর্তাবলীতে" else "Hospital Listing Terms & Policy",
                            Color(0xFF0288D1)
                        )
                        "Ambulance" -> Pair(
                            if (language == AppLanguage.BAN) "অ্যাম্বুলেন্স সার্ভিস নীতি ও শর্তাবলীতে" else "Ambulance Service Terms & Policy",
                            Color(0xFFD32F2F)
                        )
                        "Requester" -> Pair(
                            if (language == AppLanguage.BAN) "রক্ত গ্রহীতা নীতি ও শর্তাবলীতে" else "Blood Seeker Terms & Policy",
                            Color(0xFFE65100)
                        )
                        else -> Pair(
                            if (language == AppLanguage.BAN) "ডোনার নিবন্ধন নীতি ও শর্তাবলীতে" else "Donor Registration Terms & Policy",
                            BloodRed
                        )
                    }

                    Checkbox(
                        checked = regPolicyAgreed,
                        onCheckedChange = { regPolicyAgreed = it },
                        colors = CheckboxDefaults.colors(checkedColor = policyThemeColor)
                    )

                    val policyText = androidx.compose.ui.text.buildAnnotatedString {
                        append(if (language == AppLanguage.BAN) "আমি " else "I agree to the ")
                        pushStyle(
                            androidx.compose.ui.text.SpanStyle(
                                color = policyThemeColor,
                                fontWeight = FontWeight.Bold,
                                textDecoration = androidx.compose.ui.text.style.TextDecoration.Underline
                            )
                        )
                        append(policyTitle)
                        pop()
                        append(if (language == AppLanguage.BAN) " সম্মত।" else ".")
                    }

                    Text(
                        text = policyText,
                        fontSize = 12.sp,
                        color = DarkText,
                        modifier = Modifier
                            .weight(1f)
                            .clickable { showDonorPolicyDialog = true }
                    )
                }
            }

            if (showDonorPolicyDialog) {
                DonorRegistrationPolicyDialog(
                    accountType = regAccountType,
                    language = language,
                    onDismiss = { showDonorPolicyDialog = false },
                    onAgree = {
                        regPolicyAgreed = true
                        showDonorPolicyDialog = false
                    }
                )
            }

            Spacer(modifier = Modifier.height(12.dp))

            Button(
                onClick = {
                    if (!regPolicyAgreed) {
                        Toast.makeText(
                            context,
                            if (language == AppLanguage.BAN) "নিবন্ধন করতে পলিসিতে টিক চিহ্ন দিয়ে সম্মত হন!" else "Please agree to the Registration Policy to proceed!",
                            Toast.LENGTH_LONG
                        ).show()
                    } else if (regAccountType == "Hospital") {
                        if (hospNameInput.isBlank() || hospPhoneInput.isBlank()) {
                            Toast.makeText(context, if (language == AppLanguage.BAN) "হাসপাতালের নাম এবং যোগাযোগের ফোন নম্বর বাধ্যতামূলক!" else "Hospital Name and Phone are required!", Toast.LENGTH_SHORT).show()
                        } else {
                            val ok = viewModel.triggerHospitalSignup(
                                name = hospNameInput,
                                type = hospTypeInput,
                                address = hospAddressInput,
                                district = regDistrictInput.ifBlank { "Dhaka" },
                                upazila = regUpazilaInput.ifBlank { "Dhanmondi" },
                                phone = hospPhoneInput,
                                email = hospEmailInput,
                                password = hospPasswordInput,
                                services = hospServicesInput,
                                bloodAvailability = hospBloodAvailInput,
                                country = regCountryInput
                            )
                            if (ok) showSignupSuccessPopup = true
                        }
                    } else if (regAccountType == "Doctor") {
                        if (docNameInput.isBlank() || docPhoneInput.isBlank()) {
                            Toast.makeText(context, if (language == AppLanguage.BAN) "ডাক্তারের নাম এবং যোগাযোগের ফোন নম্বর বাধ্যতামূলক!" else "Doctor Name and Phone are required!", Toast.LENGTH_SHORT).show()
                        } else {
                            val ok = viewModel.triggerDoctorSignup(
                                name = docNameInput,
                                degree = docDegreeInput,
                                specialty = docSpecialtyInput,
                                hospitalName = docHospitalNameInput,
                                chamberAddress = docChamberAddressInput,
                                district = regDistrictInput.ifBlank { "Dhaka" },
                                upazila = regUpazilaInput.ifBlank { "Dhanmondi" },
                                phone = docPhoneInput,
                                email = docEmailInput,
                                password = docPasswordInput,
                                visitingHours = docVisitingHoursInput,
                                consultationFee = docFeeInput,
                                country = regCountryInput
                            )
                            if (ok) showSignupSuccessPopup = true
                        }
                    } else {
                        if (regNameInput.isBlank() || regPhoneInput.isBlank()) {
                            Toast.makeText(context, if (language == AppLanguage.BAN) "নাম এবং ফোন নম্বর দেওয়া বাধ্যতামূলক!" else "Name and Phone are mandatory!", Toast.LENGTH_SHORT).show()
                        } else {
                            viewModel.regName = regNameInput
                            viewModel.regPhone = regPhoneInput
                            viewModel.regEmail = regEmailInput
                            viewModel.regPassword = regPasswordInput
                            viewModel.regBloodGroup = regBloodInput
                            viewModel.regDistrict = regDistrictInput
                            viewModel.regUpazila = regUpazilaInput
                            viewModel.regVillage = regVillageInput
                            viewModel.regLastDonation = if (regRoleInput == "Donor") regLastDonationInput else "N/A"
                            viewModel.regCountry = regCountryInput
                            viewModel.regRole = regRoleInput

                            val ok = viewModel.triggerSignup()
                            if (ok) {
                                showSignupSuccessPopup = true
                            }
                        }
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(54.dp)
                    .testTag("register_btn"),
                colors = ButtonDefaults.buttonColors(
                    containerColor = when (regAccountType) {
                        "Hospital" -> Color(0xFF1565C0)
                        "Doctor" -> Color(0xFF2E7D32)
                        else -> BloodRed
                    }
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Text(
                    text = when (regAccountType) {
                        "Hospital" -> if (language == AppLanguage.BAN) "হাসপাতাল একাউন্ট রেজিস্ট্রেশন সম্পন্ন করুন" else "Register Hospital Account"
                        "Doctor" -> if (language == AppLanguage.BAN) "ডাক্তার একাউন্ট রেজিস্ট্রেশন সম্পন্ন করুন" else "Register Doctor Account"
                        else -> strings["btn_register"] ?: "Register"
                    },
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            OutlinedButton(
                onClick = {
                    viewModel.clearBackStackAndNavigateTo(AppScreen.HOME)
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(54.dp)
                    .testTag("reg_continue_guest_btn"),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.5.dp, BloodRed),
                colors = ButtonDefaults.outlinedButtonColors(contentColor = BloodRed)
            ) {
                Icon(Icons.Filled.PersonOutline, contentDescription = "Guest")
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (language == AppLanguage.BAN) "অতিথি হিসেবে প্রবেশ করুন" else "Continue as Guest",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }

    if (showLoginSuccessPopup) {
        val isBn = language == AppLanguage.BAN
        val isAmbulance = viewModel.currentUser.collectAsState().value?.role == "Ambulance"
        val targetScreen = if (isAmbulance) AppScreen.AMBULANCE_DASHBOARD else AppScreen.HOME
        AlertDialog(
            onDismissRequest = {
                showLoginSuccessPopup = false
                viewModel.clearBackStackAndNavigateTo(targetScreen)
            },
            icon = {
                Icon(
                    imageVector = Icons.Filled.CheckCircle,
                    contentDescription = "Success",
                    tint = Color(0xFF2E7D32),
                    modifier = Modifier.size(54.dp)
                )
            },
            title = {
                Text(
                    text = if (isBn) "লগইন সফল হয়েছে!" else "Login Successful!",
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF2E7D32),
                    fontSize = 20.sp
                )
            },
            text = {
                Text(
                    text = if (isBn) {
                        if (isAmbulance) "স্বাগতম! আপনি সফলভাবে অ্যাম্বুলেন্স চালক/মালিক ড্যাশবোর্ডে প্রবেশ করেছেন।" else "স্বাগতম! আপনি সফলভাবে আপনার অ্যাকাউন্টে লগইন করেছেন। রক্তদান করুন ও জীবন বাঁচান।"
                    } else {
                        if (isAmbulance) "Welcome! You have successfully logged into your Ambulance Dashboard." else "Welcome back! You have successfully logged into your account. Keep donating blood to save lives."
                    },
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    fontSize = 14.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        showLoginSuccessPopup = false
                        viewModel.clearBackStackAndNavigateTo(targetScreen)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isBn) {
                            if (isAmbulance) "ড্যাশবোর্ডে যান" else "হোমে যান"
                        } else {
                            if (isAmbulance) "Go to Dashboard" else "Go to Home"
                        },
                        color = Color.White,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        )
    }

    if (showSignupSuccessPopup) {
        val isBn = language == AppLanguage.BAN
        val role = viewModel.currentUser.collectAsState().value?.role ?: regAccountType
        val isAmbulance = role == "Ambulance"
        val targetScreen = when (role) {
            "Hospital" -> AppScreen.HOSPITAL_DIRECTORY
            "Doctor" -> AppScreen.DOCTOR_DIRECTORY
            "Ambulance" -> AppScreen.AMBULANCE_LIST
            else -> AppScreen.HOME
        }
        AlertDialog(
            onDismissRequest = {
                showSignupSuccessPopup = false
                if (role == "Hospital" || role == "Doctor" || role == "Ambulance") {
                    viewModel.triggerAutoShowPlan(role)
                }
                viewModel.clearBackStackAndNavigateTo(targetScreen)
            },
            icon = {
                Icon(
                    imageVector = Icons.Filled.CheckCircle,
                    contentDescription = "Success",
                    tint = Color(0xFF2E7D32),
                    modifier = Modifier.size(54.dp)
                )
            },
            title = {
                Text(
                    text = if (isBn) "নিবন্ধন সফল হয়েছে!" else "Registration Successful!",
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF2E7D32),
                    fontSize = 20.sp
                )
            },
            text = {
                Text(
                    text = if (isBn) {
                        when (role) {
                            "Doctor" -> "অভিনন্দন! আপনার ডাক্তার অ্যাকাউন্ট সফলভাবে তৈরি হয়েছে। এবার প্ল্যান বেছে নিয়ে আপনার প্রোফাইল অ্যাক্টিভ করুন।"
                            "Hospital" -> "অভিনন্দন! আপনার হাসপাতাল অ্যাকাউন্ট সফলভাবে তৈরি হয়েছে। এবার প্ল্যান বেছে নিয়ে লিস্টিং অ্যাক্টিভ করুন।"
                            "Ambulance" -> "অভিনন্দন! আপনার অ্যাম্বুলেন্স অ্যাকাউন্ট সফলভাবে তৈরি করা হয়েছে। প্ল্যান নির্বাচন করে সার্ভিস চালু করুন।"
                            else -> "অভিনন্দন! আপনার অ্যাকাউন্টটি সফলভাবে তৈরি করা হয়েছে।"
                        }
                    } else {
                        when (role) {
                            "Doctor" -> "Congratulations! Your Doctor account has been created. Select a plan to activate your chamber profile."
                            "Hospital" -> "Congratulations! Your Hospital account has been created. Select a plan to activate your listing."
                            "Ambulance" -> "Congratulations! Your Ambulance driver/owner account has been created successfully."
                            else -> "Congratulations! Your account has been created successfully."
                        }
                    },
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                    fontSize = 14.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        showSignupSuccessPopup = false
                        if (role == "Hospital" || role == "Doctor" || role == "Ambulance") {
                            viewModel.triggerAutoShowPlan(role)
                        }
                        viewModel.clearBackStackAndNavigateTo(targetScreen)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isBn) {
                            if (role == "Hospital" || role == "Doctor" || role == "Ambulance") "প্ল্যান নির্বাচন করুন" else "হোমে যান"
                        } else {
                            if (role == "Hospital" || role == "Doctor" || role == "Ambulance") "Select Plan" else "Go to Home"
                        },
                        color = Color.White,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        )
    }
}


// --- 3. HOME SCREEN ---

@Composable
fun HomeScreen(viewModel: MainViewModel) {
    val strings by viewModel.strings.collectAsState()
    val appName by viewModel.appName.collectAsState()
    val homeNotice by viewModel.homeNotice.collectAsState()
    val popupNotice by viewModel.popupNotice.collectAsState()
    val statistics by viewModel.statistics.collectAsState()
    val userSession by viewModel.currentUser.collectAsState()
    val requests by viewModel.requests.collectAsState()
    val language by viewModel.language.collectAsState()
    val detectedCountry by viewModel.detectedCountry.collectAsState()
    val detectedCountryCode by viewModel.detectedCountryCode.collectAsState()
    val isDeviceInBangladesh by viewModel.isDeviceInBangladesh.collectAsState()
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    val displayHomeNotice = remember(homeNotice, language) {
        if (language == AppLanguage.ENG) {
            if (homeNotice == "স্বাগতম আলিফ ব্লাড ব্যাংকে! জরুরি প্রয়োজনে চ্যাট বা কল করুন।" || homeNotice.contains("স্বাগতম") || homeNotice.contains("আলিফ") || homeNotice.contains("জরুরি")) {
                "Welcome to Alif Blood Bank! Chat or call in case of emergency."
            } else {
                homeNotice
            }
        } else {
            homeNotice
        }
    }

    val displayPopupNotice = remember(popupNotice, language) {
        if (language == AppLanguage.ENG) {
            if (popupNotice == "আমাদের অ্যাপটি নিয়মিত আপডেট করুন এবং রক্ত দানে উৎসাহিত হোন।" || popupNotice.contains("আমাদের অ্যাপটি") || popupNotice.contains("উৎসাহিত") || popupNotice.contains("রক্ত দানে")) {
                "Please update our app regularly and be encouraged to donate blood."
            } else {
                popupNotice
            }
        } else {
            popupNotice
        }
    }

    var showGiftPopup by rememberSaveable(popupNotice) { mutableStateOf(popupNotice.isNotEmpty()) }

    val networkCountryBn = when (detectedCountry) {
        "Bangladesh" -> "বাংলাদেশ"
        "United States" -> "যুক্তরাষ্ট্র"
        "India" -> "ভারত"
        "Saudi Arabia" -> "সৌদি আরব"
        "United Arab Emirates" -> "সংযুক্ত আরব আমিরাত"
        "United Kingdom" -> "যুক্তরাজ্য"
        else -> detectedCountry
    }

    var showCountryChangeDialog by remember { mutableStateOf(false) }
    var showSwitchWarningDialog by remember { mutableStateOf(false) }
    var isNoticeDismissed by rememberSaveable(homeNotice) { mutableStateOf(false) }
    var showSupportDialog by remember { mutableStateOf(false) }

    if (showGiftPopup && popupNotice.isNotEmpty()) {
        AlertDialog(
            onDismissRequest = { showGiftPopup = false },
            containerColor = Color.White,
            shape = RoundedCornerShape(24.dp),
            icon = {
                Box(
                    modifier = Modifier
                        .size(80.dp)
                        .background(BloodRed.copy(alpha = 0.1f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Filled.CardGiftcard,
                        contentDescription = "Gift",
                        tint = BloodRed,
                        modifier = Modifier.size(40.dp)
                    )
                }
            },
            title = {
                Text(
                    text = if (language == AppLanguage.ENG) "Special Announcement!" else "বিশেষ ঘোষণা!",
                    fontWeight = FontWeight.ExtraBold,
                    fontSize = 22.sp,
                    color = BloodRed,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth()
                )
            },
            text = {
                Text(
                    text = displayPopupNotice,
                    fontSize = 16.sp,
                    color = DarkText,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                    lineHeight = 22.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = { showGiftPopup = false },
                    modifier = Modifier.fillMaxWidth().height(54.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = BloodRed),
                    shape = RoundedCornerShape(16.dp)
                ) {
                    Text(
                        text = if (language == AppLanguage.ENG) "Okay, Got it!" else "ঠিক আছে, বুঝেছি!",
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp
                    )
                }
            }
        )
    }

    val quickCountries by viewModel.customCountries.collectAsState()

    if (showCountryChangeDialog) {
        val isBn = language == AppLanguage.BAN
        AlertDialog(
            onDismissRequest = { showCountryChangeDialog = false },
            title = {
                Text(
                    text = if (isBn) "সার্ভার দেশ নির্বাচন করুন" else "Select Server Country",
                    fontWeight = FontWeight.Bold,
                    color = BloodRed,
                    fontSize = 18.sp
                )
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // VPN sync / detection button at the top
                    Button(
                        onClick = {
                            scope.launch {
                                android.widget.Toast.makeText(context, if (isBn) "ভিপিএন / আইপি সংযোগ চেক করা হচ্ছে..." else "Checking VPN / IP connection...", android.widget.Toast.LENGTH_SHORT).show()
                                viewModel.detectUserLocation(context)
                                kotlinx.coroutines.delay(1500)
                                val current = viewModel.detectedCountry.value
                                android.widget.Toast.makeText(context, if (isBn) "আইপি রিফ্রেশ করা হয়েছে। বর্তমান সার্ভার: $current" else "IP refreshed. Active server: $current", android.widget.Toast.LENGTH_LONG).show()
                                showCountryChangeDialog = false
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = BloodRed, contentColor = Color.White),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Icon(imageVector = Icons.Filled.Sync, contentDescription = "VPN Sync")
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(text = if (isBn) "ভিপিএন / আইপি রিফ্রেশ করুন" else "Refresh IP / VPN", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    Text(
                        text = if (isBn) {
                            "আইপি অনুযায়ী আপনার বর্তমান সার্ভার: $detectedCountry"
                        } else {
                            "Your current server based on IP: $detectedCountry"
                        },
                        fontSize = 13.sp,
                        color = Color.Gray,
                        modifier = Modifier.padding(bottom = 6.dp)
                    )
                    
                    val staticCountries = listOf(
                        Pair("Bangladesh", "বাংলাদেশ"),
                        Pair("India", "ভারত"),
                        Pair("Saudi Arabia", "সৌদি আরব"),
                        Pair("United Arab Emirates", "সংযুক্ত আরব আমিরাত"),
                        Pair("United States", "যুক্তরাষ্ট্র"),
                        Pair("United Kingdom", "যুক্তরাজ্য")
                    )
                    
                    val allCountries = (staticCountries + quickCountries.map { Pair(it.first, it.second) }).distinctBy { it.first }
                    
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(max = 250.dp)
                            .verticalScroll(rememberScrollState())
                    ) {
                        allCountries.forEach { (name, nativeName) ->
                            val isCurrent = name.equals(detectedCountry, ignoreCase = true)
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isCurrent) Color(0xFFFFEBEE) else Color.Transparent)
                                    .clickable {
                                        if (!isCurrent) {
                                            showSwitchWarningDialog = true
                                        }
                                        showCountryChangeDialog = false
                                    }
                                    .padding(horizontal = 12.dp, vertical = 10.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                RadioButton(
                                    selected = isCurrent,
                                    onClick = {
                                        if (!isCurrent) {
                                            showSwitchWarningDialog = true
                                        }
                                        showCountryChangeDialog = false
                                    },
                                    colors = RadioButtonDefaults.colors(selectedColor = BloodRed)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Column {
                                    Text(
                                        text = name,
                                        fontSize = 14.sp,
                                        fontWeight = if (isCurrent) FontWeight.Bold else FontWeight.Medium,
                                        color = if (isCurrent) BloodRed else Color.DarkGray
                                    )
                                    Text(
                                        text = nativeName,
                                        fontSize = 11.sp,
                                        color = Color.Gray
                                    )
                                }
                                if (isCurrent) {
                                    Spacer(modifier = Modifier.weight(1f))
                                    Text(
                                        text = if (isBn) "সংযুক্ত" else "Connected",
                                        fontSize = 10.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF2E7D32),
                                        modifier = Modifier
                                            .background(Color(0xFFE8F5E9), RoundedCornerShape(4.dp))
                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                TextButton(
                    onClick = { showCountryChangeDialog = false }
                ) {
                    Text(if (isBn) "বন্ধ করুন" else "Close", color = Color.Gray)
                }
            }
        )
    }

    if (showSwitchWarningDialog) {
        val isBn = language == AppLanguage.BAN
        AlertDialog(
            onDismissRequest = { showSwitchWarningDialog = false },
            title = {
                Text(
                    text = if (isBn) "সার্ভার সংযোগ নোটিশ" else "Server Connection Notice",
                    fontWeight = FontWeight.Bold,
                    color = BloodRed,
                    fontSize = 18.sp
                )
            },
            text = {
                Text(
                    text = if (isBn) {
                        "আপনার ডিভাইসটি আইপি অনুযায়ী স্বয়ংক্রিয়ভাবে $detectedCountry সার্ভারে সংযুক্ত আছে। নিরাপত্তাজনিত কারণে অন্য সার্ভার নির্বাচন করা সম্ভব নয়।"
                    } else {
                        "Your device is automatically connected to the $detectedCountry server based on your IP. For security reasons, selecting other servers is not permitted."
                    },
                    fontSize = 14.sp,
                    color = Color.DarkGray
                )
            },
            confirmButton = {
                TextButton(
                    onClick = { 
                        showSwitchWarningDialog = false 
                        showCountryChangeDialog = false
                    },
                    modifier = Modifier.testTag("ok_server_notice_btn")
                ) {
                    Text(if (isBn) "ওকে" else "OK", color = BloodRed, fontWeight = FontWeight.Bold)
                }
            }
        )
    }

