        @Composable
        fun CpaAdVideoPlayer(videoPath: String, modifier: Modifier = Modifier) {
            val context = androidx.compose.ui.platform.LocalContext.current
            val lifecycleOwner = androidx.lifecycle.compose.LocalLifecycleOwner.current

            val ytId = remember(videoPath) {
                try {
                    when {
                        videoPath.contains("youtu.be/") -> videoPath.substringAfter("youtu.be/").substringBefore("?").substringBefore("&").substringBefore("/")
                        videoPath.contains("youtube.com/watch") -> android.net.Uri.parse(videoPath).getQueryParameter("v")
                        videoPath.contains("youtube.com/embed/") -> videoPath.substringAfter("youtube.com/embed/").substringBefore("?").substringBefore("&").substringBefore("/")
                        videoPath.contains("youtube.com/shorts/") -> videoPath.substringAfter("youtube.com/shorts/").substringBefore("?").substringBefore("&").substringBefore("/")
                        else -> null
                    }
                } catch (e: Exception) { null }
            }

            val driveId = remember(videoPath) {
                try {
                    when {
                        videoPath.contains("drive.google.com/file/d/") -> videoPath.substringAfter("drive.google.com/file/d/").substringBefore("/")
                        videoPath.contains("drive.google.com/open?id=") -> videoPath.substringAfter("drive.google.com/open?id=").substringBefore("&")
                        videoPath.contains("drive.google.com/uc?") -> android.net.Uri.parse(videoPath).getQueryParameter("id")
                        else -> null
                    }
                } catch (e: Exception) { null }
            }

            val isWebEmbed = ytId != null || driveId != null || videoPath.contains("vimeo.com") || videoPath.endsWith(".html")

            if (isWebEmbed) {
                val embedHtml = remember(videoPath, ytId, driveId) {
                    when {
                        ytId != null -> """
                            <!DOCTYPE html>
                            <html>
                            <head>
                            <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
                            <style>
                              body, html { margin: 0; padding: 0; width: 100%; height: 100%; background-color: #000; overflow: hidden; }
                              iframe { width: 100%; height: 100%; border: none; }
                            </style>
                            </head>
                            <body>
                              <iframe src="https://www.youtube.com/embed/$ytId?autoplay=1&mute=1&playsinline=1&controls=1&loop=1&playlist=$ytId" allow="autoplay; encrypted-media; fullscreen" allowfullscreen></iframe>
                            </body>
                            </html>
                        """.trimIndent()
                        driveId != null -> """
                            <!DOCTYPE html>
                            <html>
                            <head>
                            <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
                            <style>
                              body, html { margin: 0; padding: 0; width: 100%; height: 100%; background-color: #000; overflow: hidden; }
                              iframe { width: 100%; height: 100%; border: none; }
                            </style>
                            </head>
                            <body>
                              <iframe src="https://drive.google.com/file/d/$driveId/preview" allow="autoplay; fullscreen" allowfullscreen></iframe>
                            </body>
                            </html>
                        """.trimIndent()
                        else -> """
                            <!DOCTYPE html>
                            <html>
                            <head>
                            <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
                            <style>
                              body, html { margin: 0; padding: 0; width: 100%; height: 100%; background-color: #000; overflow: hidden; }
                              iframe { width: 100%; height: 100%; border: none; }
                            </style>
                            </head>
                            <body>
                              <iframe src="$videoPath" allow="autoplay; fullscreen" allowfullscreen></iframe>
                            </body>
                            </html>
                        """.trimIndent()
                    }
                }

                androidx.compose.ui.viewinterop.AndroidView(
                    factory = { ctx ->
                        android.webkit.WebView(ctx).apply {
                            layoutParams = android.view.ViewGroup.LayoutParams(
                                android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                                android.view.ViewGroup.LayoutParams.MATCH_PARENT
                            )
                            settings.javaScriptEnabled = true
                            settings.domStorageEnabled = true
                            settings.mediaPlaybackRequiresUserGesture = false
                            settings.loadWithOverviewMode = true
                            settings.useWideViewPort = true
                            webChromeClient = android.webkit.WebChromeClient()
                            webViewClient = object : android.webkit.WebViewClient() {
                                override fun shouldOverrideUrlLoading(view: android.webkit.WebView?, request: android.webkit.WebResourceRequest?): Boolean {
                                    return false
                                }
                            }
                            loadDataWithBaseURL("https://www.youtube.com", embedHtml, "text/html", "UTF-8", null)
                        }
                    },
                    modifier = modifier
                )
            } else {
                val videoUri = remember(videoPath) {
                    if (videoPath.startsWith("/")) {
                        android.net.Uri.fromFile(java.io.File(videoPath))
                    } else {
                        android.net.Uri.parse(videoPath)
                    }
                }

                var videoViewRef by remember { mutableStateOf<android.widget.VideoView?>(null) }

                androidx.compose.runtime.DisposableEffect(lifecycleOwner, videoUri) {
                    val observer = androidx.lifecycle.LifecycleEventObserver { _, event ->
                        if (event == androidx.lifecycle.Lifecycle.Event.ON_RESUME) {
                            videoViewRef?.let { vv ->
                                try {
                                    if (!vv.isPlaying) {
                                        vv.setVideoURI(videoUri)
                                        vv.start()
                                    }
                                } catch (e: Exception) {
                                    e.printStackTrace()
                                }
                            }
                        } else if (event == androidx.lifecycle.Lifecycle.Event.ON_PAUSE) {
                            videoViewRef?.let { vv ->
                                try {
                                    if (vv.isPlaying) {
                                        vv.pause()
                                    }
                                } catch (e: Exception) {
                                    e.printStackTrace()
                                }
                            }
                        }
                    }
                    lifecycleOwner.lifecycle.addObserver(observer)
                    onDispose {
                        lifecycleOwner.lifecycle.removeObserver(observer)
                    }
                }

                androidx.compose.ui.viewinterop.AndroidView(
                    factory = { ctx ->
                        android.widget.VideoView(ctx).apply {
                            videoViewRef = this
                            setOnPreparedListener { mp ->
                                mp.isLooping = true
                                mp.setVolume(0f, 0f) // Mute by default for banner ads
                                mp.start()
                            }
                            setOnErrorListener { _, _, _ ->
                                true // Prevent crash error dialogs
                            }
                            try {
                                setVideoURI(videoUri)
                                start()
                            } catch (e: Exception) {
                                e.printStackTrace()
                            }
                        }
                    },
                    update = { vv ->
                        videoViewRef = vv
                        try {
                            if (!vv.isPlaying) {
                                vv.setVideoURI(videoUri)
                                vv.start()
                            }
                        } catch (e: Exception) {
                            e.printStackTrace()
                        }
                    },
                    modifier = modifier
                )
            }
        }

        val customAdsEnabled by viewModel.customAdsEnabled.collectAsState()
        val customAdConfigs by viewModel.customAdConfigs.collectAsState()
        val customAdNetworkName by viewModel.customAdNetworkName.collectAsState()
        val customAdTitle by viewModel.customAdTitle.collectAsState()
        val customAdBannerUrl by viewModel.customAdBannerUrl.collectAsState()
        val customAdTargetUrl by viewModel.customAdTargetUrl.collectAsState()
        val customAdTargetCountries by viewModel.customAdTargetCountries.collectAsState()

        val activeAdsForCountry = remember(customAdConfigs, customAdTitle, customAdNetworkName, customAdBannerUrl, customAdTargetUrl, customAdTargetCountries, detectedCountry) {
            fun isCountryMatched(targetStr: String): Boolean {
                if (targetStr.isBlank()) return true
                val countries = targetStr.split(",").map { it.trim() }
                return countries.any { country ->
                    country.equals("All", ignoreCase = true) ||
                    country.equals("International", ignoreCase = true) ||
                    country.equals(detectedCountry, ignoreCase = true) ||
                    (country.equals("BD", ignoreCase = true) && detectedCountry.equals("Bangladesh", ignoreCase = true)) ||
                    (country.equals("Bangladesh", ignoreCase = true) && (detectedCountry.equals("BD", ignoreCase = true) || detectedCountry.equals("Bangladesh", ignoreCase = true))) ||
                    (country.equals("USA", ignoreCase = true) && (detectedCountry.contains("United States", ignoreCase = true) || detectedCountry.equals("US", ignoreCase = true))) ||
                    (country.equals("UK", ignoreCase = true) && (detectedCountry.contains("United Kingdom", ignoreCase = true) || detectedCountry.equals("GB", ignoreCase = true))) ||
                    (country.equals("UAE", ignoreCase = true) && (detectedCountry.contains("Emirates", ignoreCase = true) || detectedCountry.equals("AE", ignoreCase = true))) ||
                    (country.equals("SA", ignoreCase = true) && (detectedCountry.contains("Saudi", ignoreCase = true) || detectedCountry.equals("SA", ignoreCase = true))) ||
                    (country.equals("IN", ignoreCase = true) && (detectedCountry.equals("India", ignoreCase = true) || detectedCountry.equals("IN", ignoreCase = true)))
                }
            }

            val filtered = customAdConfigs.filter { isCountryMatched(it.targetCountries) }
            if (filtered.isNotEmpty()) {
                filtered
            } else if (customAdTitle.isNotBlank() && isCountryMatched(customAdTargetCountries)) {
                listOf(
                    com.example.data.CustomAdConfig(
                        id = "default_single_ad",
                        networkName = customAdNetworkName.ifBlank { "Affmine" },
                        title = customAdTitle,
                        bannerUrl = customAdBannerUrl,
                        targetUrl = customAdTargetUrl,
                        targetCountries = customAdTargetCountries
                    )
                )
            } else {
                listOf(
                    com.example.data.CustomAdConfig(
                        id = "fallback_affmine_ad",
                        networkName = if (customAdNetworkName.isNotBlank()) customAdNetworkName else "Affmine",
                        title = if (customAdTitle.isNotBlank()) customAdTitle else "Earn Money with Affmine CPA Offers!",
                        bannerUrl = if (customAdBannerUrl.isNotBlank()) customAdBannerUrl else "https://images.unsplash.com/photo-1542744094-3a31f103e35f?auto=format&fit=crop&w=600&q=80",
                        targetUrl = if (customAdTargetUrl.isNotBlank()) customAdTargetUrl else "https://www.affmine.com",
                        targetCountries = "All"
                    )
                )
            }
        }

        if (customAdsEnabled && activeAdsForCountry.isNotEmpty()) {
            val selectedAd = remember(activeAdsForCountry) {
                val totalWeight = activeAdsForCountry.sumOf { it.weight.coerceAtLeast(1) }
                if (totalWeight <= 0) {
                    activeAdsForCountry.first()
                } else {
                    var randomVal = (1..totalWeight).random()
                    var selected = activeAdsForCountry.first()
                    for (ad in activeAdsForCountry) {
                        randomVal -= ad.weight.coerceAtLeast(1)
                        if (randomVal <= 0) {
                            selected = ad
                            break
                        }
                    }
                    selected
                }
            }

            val context = androidx.compose.ui.platform.LocalContext.current
            val uriHandler = androidx.compose.ui.platform.LocalUriHandler.current

            val openCpaLink = {
                val rawUrl = selectedAd.targetUrl.trim()
                if (rawUrl.isNotEmpty()) {
                    val formattedUrl = if (!rawUrl.startsWith("http://") && !rawUrl.startsWith("https://")) {
                        "https://$rawUrl"
                    } else {
                        rawUrl
                    }
                    try {
                        val intent = android.content.Intent(
                            android.content.Intent.ACTION_VIEW,
                            android.net.Uri.parse(formattedUrl)
                        ).apply {
                            addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
                        }
                        context.startActivity(intent)
                    } catch (e: Exception) {
                        e.printStackTrace()
                        try {
                            uriHandler.openUri(formattedUrl)
                        } catch (ex: Exception) {
                            ex.printStackTrace()
                            android.widget.Toast.makeText(
                                context,
                                if (language == AppLanguage.BAN) "লিংক খুলতে ব্যর্থ হয়েছে: $formattedUrl" else "Could not open link: $formattedUrl",
                                android.widget.Toast.LENGTH_SHORT
                            ).show()
                        }
                    }
                }
            }

            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 12.dp)
                    .clickable { openCpaLink() }
                    .shadow(4.dp, RoundedCornerShape(12.dp)),
                shape = RoundedCornerShape(12.dp),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                border = BorderStroke(1.5.dp, BloodRed.copy(alpha = 0.4f))
            ) {
                Column {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(BloodRed.copy(alpha = 0.08f))
                            .padding(horizontal = 12.dp, vertical = 6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.Filled.Star,
                                contentDescription = null,
                                tint = BloodRed,
                                modifier = Modifier.size(14.dp)
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            Text(
                                text = selectedAd.networkName.uppercase() + " SPONSORED OFFER",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = BloodRed
                            )
                        }
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                text = if (language == AppLanguage.BAN) "বিজ্ঞাপন" else "AD",
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold,
                                color = SecondaryText,
                                modifier = Modifier
                                    .background(LightBorder, RoundedCornerShape(3.dp))
                                    .padding(horizontal = 4.dp, vertical = 1.dp)
                            )
                        }
                    }

                    if (selectedAd.isVideo && (selectedAd.videoUrl.isNotEmpty() || selectedAd.bannerUrl.isNotEmpty())) {
                        val videoPath = if (selectedAd.videoUrl.isNotEmpty()) selectedAd.videoUrl else selectedAd.bannerUrl
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(160.dp)
                                .background(Color.Black),
                            contentAlignment = Alignment.Center
                        ) {
                            CpaAdVideoPlayer(
                                videoPath = videoPath,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    } else {
                        val imageModel = remember(selectedAd.bannerUrl) {
                            if (selectedAd.bannerUrl.startsWith("/")) {
                                java.io.File(selectedAd.bannerUrl)
                            } else {
                                selectedAd.bannerUrl
                            }
                        }
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(130.dp)
                                .background(Color.LightGray)
                        ) {
                            coil.compose.AsyncImage(
                                model = imageModel,
                                contentDescription = "CPA Ad Offer",
                                modifier = Modifier.fillMaxSize(),
                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                        }
                    }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column(modifier = Modifier.weight(1f).padding(end = 8.dp)) {
                            Text(
                                text = selectedAd.title,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = DarkText,
                                maxLines = 1,
                                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                            )
                            Text(
                                text = if (language == AppLanguage.BAN) "অফিসিয়াল স্পন্সরড অফার • " + selectedAd.networkName else "Official Partner Offer • " + selectedAd.networkName,
                                fontSize = 10.sp,
                                color = SecondaryText,
                                maxLines = 1,
                                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                            )
                        }

                        Button(
                            onClick = { openCpaLink() },
                            colors = ButtonDefaults.buttonColors(containerColor = BloodRed),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.height(30.dp)
                        ) {
                            Text(
                                text = if (language == AppLanguage.BAN) "ভিজিট করুন" else "Visit Now",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(12.dp))

        // Grid Statistics Cards (Blood Network Today)
        Text(
            text = if (language == AppLanguage.BAN) "$networkCountryBn ব্লাড নেটওয়ার্ক আজ" else "$detectedCountry Blood Network Today",
            fontWeight = FontWeight.Bold,
            fontSize = 16.sp,
            color = DarkText,
            modifier = Modifier.padding(bottom = 10.dp)
        )

        // Live Dynamic Stats Row (Matching User Image Design)
        Card(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 16.dp),
            shape = RoundedCornerShape(8.dp),
            border = BorderStroke(4.dp, Color.White), // White border for contrast
            colors = CardDefaults.cardColors(containerColor = BloodRed) // Red background
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                // Total Users Card
                Card(
                    modifier = Modifier.weight(1f),
                    colors = CardDefaults.cardColors(containerColor = Color.Transparent), // Transparent to show parent red
                    shape = RoundedCornerShape(4.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Person,
                            contentDescription = null,
                            tint = Color.White, // White icon
                            modifier = Modifier.size(32.dp)
                        )
                        val totalUsersTarget = (statistics["total_users"] ?: 80424).toFloat()
                        var startCount by remember { mutableStateOf(false) }
                        val animatedUsers by animateFloatAsState(
                            targetValue = if (startCount) totalUsersTarget else 1f,
                            animationSpec = tween(durationMillis = 2500, easing = LinearOutSlowInEasing),
                            label = "users_count"
                        )
                        LaunchedEffect(Unit) {
                            startCount = true
                        }
                        val usersText = remember(animatedUsers) {
                            val countVal = animatedUsers.toInt()
                            if (countVal >= 1000) "${countVal / 1000}k" else countVal.toString()
                        }
                        Text(
                            text = usersText,
                            color = Color.White, // White text
                            fontSize = 24.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = strings["stat_total_users"] ?: "Total Customer",
                            color = Color.White.copy(alpha = 0.9f), // White label
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                // Divider (Vertical Line)
                Box(
                    modifier = Modifier
                        .width(4.dp)
                        .fillMaxHeight()
                        .background(Color.White)
                )

                // Total Donors Card (Total Donor)
                Card(
                    modifier = Modifier.weight(1f),
                    colors = CardDefaults.cardColors(containerColor = Color.Transparent),
                    shape = RoundedCornerShape(4.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Favorite,
                            contentDescription = null,
                            tint = Color.White, // White icon
                            modifier = Modifier.size(32.dp)
                        )
                        val totalDonorsTarget = (statistics["total_donors"] ?: 12300).toFloat()
                        var startDonorCount by remember { mutableStateOf(false) }
                        val animatedDonors by animateFloatAsState(
                            targetValue = if (startDonorCount) totalDonorsTarget else 1f,
                            animationSpec = tween(durationMillis = 2500, easing = LinearOutSlowInEasing),
                            label = "donors_count"
                        )
                        LaunchedEffect(Unit) {
                            startDonorCount = true
                        }
                        val donorsText = remember(animatedDonors) {
                            val countVal = animatedDonors.toInt()
                            if (countVal >= 1000) "${countVal / 1000}k" else countVal.toString()
                        }
                        Text(
                            text = donorsText,
                            color = Color.White, // White text
                            fontSize = 24.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = strings["stat_total_donors_large"] ?: "Total Donor",
                            color = Color.White.copy(alpha = 0.9f), // White label
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(20.dp))

        // ROLE DETERMINATION FOR DASHBOARD
        val activeRole = userSession?.role?.ifBlank { "Donor" } ?: "Guest"
        val isDonorRole = userSession != null && (activeRole.equals("Donor", ignoreCase = true) || activeRole.equals("User", ignoreCase = true))
        val isRequesterRole = userSession != null && (activeRole.equals("Requester", ignoreCase = true) || activeRole.equals("Recipient", ignoreCase = true) || activeRole.equals("Patient", ignoreCase = true))
        val isHospitalRole = userSession != null && activeRole.equals("Hospital", ignoreCase = true)
        val isDoctorRole = userSession != null && activeRole.equals("Doctor", ignoreCase = true)
        val isAmbulanceRole = userSession != null && activeRole.equals("Ambulance", ignoreCase = true)

        // ROLE BANNER
        if (userSession != null) {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = when {
                        isDonorRole -> Color(0xFFFFF3E0)
                        isRequesterRole -> Color(0xFFFFEBEE)
                        isHospitalRole -> Color(0xFFE1F5FE)
                        isDoctorRole -> Color(0xFFF3E5F5)
                        isAmbulanceRole -> Color(0xFFE0F2F1)
                        else -> Color(0xFFFAFAFA)
                    }
                ),
                border = BorderStroke(
                    1.dp,
                    when {
                        isDonorRole -> Color(0xFFFFB74D)
                        isRequesterRole -> Color(0xFFEF9A9A)
                        isHospitalRole -> Color(0xFF81D4FA)
                        isDoctorRole -> Color(0xFFCE93D8)
                        isAmbulanceRole -> Color(0xFF80CBC4)
                        else -> Color(0xFFE0E0E0)
                    }
                ),
                shape = RoundedCornerShape(14.dp)
            ) {
                Column(modifier = Modifier.padding(14.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = when {
                                isDonorRole -> Icons.Filled.VolunteerActivism
                                isRequesterRole -> Icons.Filled.Queue
                                isHospitalRole -> Icons.Filled.Apartment
                                isDoctorRole -> Icons.Filled.Healing
                                isAmbulanceRole -> Icons.Filled.AirportShuttle
                                else -> Icons.Filled.Person
                            },
                            contentDescription = null,
                            tint = when {
                                isDonorRole -> Color(0xFFE65100)
                                isRequesterRole -> BloodRed
                                isHospitalRole -> Color(0xFF0288D1)
                                isDoctorRole -> Color(0xFF8E24AA)
                                isAmbulanceRole -> Color(0xFF00897B)
                                else -> DarkText
                            },
                            modifier = Modifier.size(28.dp)
                        )
                        Spacer(modifier = Modifier.width(10.dp))
                        Column {
                            Text(
                                text = when {
                                    isDonorRole -> if (language == AppLanguage.BAN) "🩸 ডোনার অ্যাকাউন্ট: ${userSession?.name}" else "🩸 Donor Account: ${userSession?.name}"
                                    isRequesterRole -> if (language == AppLanguage.BAN) "🩺 রক্তগ্রহীতা/পেশেন্ট অ্যাকাউন্ট: ${userSession?.name}" else "🩺 Patient Request Account: ${userSession?.name}"
                                    isHospitalRole -> if (language == AppLanguage.BAN) "🏥 হাসপাতাল অ্যাকাউন্ট: ${userSession?.name}" else "🏥 Hospital Care Account: ${userSession?.name}"
                                    isDoctorRole -> if (language == AppLanguage.BAN) "👨‍⚕️ ডাক্তার অ্যাকাউন্ট: ${userSession?.name}" else "👨‍⚕️ Doctor Account: ${userSession?.name}"
                                    isAmbulanceRole -> if (language == AppLanguage.BAN) "🚑 অ্যাম্বুলেন্স ড্রাইভার অ্যাকাউন্ট: ${userSession?.name}" else "🚑 Ambulance Account: ${userSession?.name}"
                                    else -> "👤 ${userSession?.name}"
                                },
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = DarkText
                            )
                            Text(
                                text = when {
