                                                docEn = dcEn, docBn = dcBn,
                                                bloodEn = bEn, bloodBn = bBn,
                                                ambEn = aEn, ambBn = aBn,
                                                hospEn = hEn, hospBn = hBn
                                            )
                                            Toast.makeText(context, if (language == AppLanguage.BAN) "সকল পলিসি সফলভাবে সংরক্ষিত হয়েছে!" else "All Policy Pages Saved Successfully!", Toast.LENGTH_SHORT).show()
                                        }
                                    )
                                }
                                "REPORTS" -> {
                                    AdminReportsTab(
                                        reports = filteredReports,
                                        language = language,
                                        onDismiss = { id ->
                                            viewModel.adminActionOnScamReport(id, "Dismissed")
                                            Toast.makeText(context, "Report dismissed", Toast.LENGTH_SHORT).show()
                                        },
                                        onBan = { id ->
                                            viewModel.adminActionOnScamReport(id, "Banned")
                                            Toast.makeText(context, "Scammer suspended and banned!", Toast.LENGTH_LONG).show()
                                        },
                                        strings = strings,
                                        donors = donorsList,
                                        onUpdateReport = { id, name, phone, amount, reason, status ->
                                            viewModel.updateScamReport(id, name, phone, amount, reason, status)
                                        },
                                        viewModel = viewModel
                                    )
                                }
                                "PLANS" -> {
                                    AdminPlansAndPricingTab(viewModel = viewModel, language = language)
                                }
                                "BOOKING_FEES" -> {
                                    AdminBookingFeesTab(viewModel = viewModel, language = language)
                                }
                                "V9_SUBSCRIPTIONS" -> {
                                    AdminSubscriptionsTab(viewModel = viewModel, language = language)
                                }
