    }
}

@Composable
fun PendingBookingCard(
    booking: AmbulanceBooking,
    language: AppLanguage,
    isBlocked: Boolean = false,
    onAccept: () -> Unit
) {
    val isBn = language == AppLanguage.BAN
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 6.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, LightBorder)
    ) {
        Column(modifier = Modifier.padding(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = booking.patientName,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = DarkText
                )
                Surface(
                    color = Color(0xFFFFF3E0),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isBn) "অপেক্ষমান" else "Pending",
                        fontSize = 10.sp,
                        color = Color(0xFFE65100),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            BookingLocationRow(
                from = booking.pickupAddress,
                to = booking.destinationAddress,
                language = language
            )

            Spacer(modifier = Modifier.height(10.dp))
            Spacer(modifier = Modifier.height(1.dp).fillMaxWidth().background(Color(0xFFF0F0F0)))
            Spacer(modifier = Modifier.height(10.dp))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Text(text = if (isBn) "ভাড়া (BDT)" else "Estimated Fare", fontSize = 11.sp, color = SecondaryText)
                    Text(text = "${booking.fare.toInt()} BDT", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = BloodRed)
                }

                Button(
                    onClick = onAccept,
                    enabled = !isBlocked,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isBlocked) Color.Gray else Color(0xFF2E7D32),
                        disabledContainerColor = Color.LightGray
                    ),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 6.dp)
                ) {
                    Icon(
                        imageVector = if (isBlocked) Icons.Default.Lock else Icons.Filled.Check,
                        contentDescription = null,
                        modifier = Modifier.size(16.dp),
                        tint = if (isBlocked) Color.DarkGray else Color.White
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = if (isBlocked) {
                            if (isBn) "সীমাবদ্ধ (বকেয়া কমিশন)" else "Blocked (Due Commission)"
                        } else {
                            if (isBn) "ভাড়া গ্রহণ করুন" else "Accept Booking"
                        },
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isBlocked) Color.DarkGray else Color.White
                    )
                }
            }
        }
    }
}

@Composable
fun ActiveTripCard(
    booking: AmbulanceBooking,
    language: AppLanguage,
    onCall: () -> Unit,
    onChat: () -> Unit,
    onUpdateStatus: () -> Unit,
    onPayCommission: () -> Unit
) {
    val isBn = language == AppLanguage.BAN

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 6.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, BloodRed.copy(alpha = 0.2f))
    ) {
        Column(modifier = Modifier.padding(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = booking.patientName,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = DarkText
                )
                Surface(
                    color = when (booking.status) {
                        "On the Way" -> Color(0xFFE0F2F1)
                        else -> Color(0xFFE3F2FD)
                    },
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isBn) {
                            when (booking.status) {
                                "On the Way" -> "পথে রয়েছে"
                                "Confirmed" -> "নিশ্চিত"
                                else -> booking.status
                            }
                        } else booking.status,
                        fontSize = 10.sp,
                        color = when (booking.status) {
                            "On the Way" -> Color(0xFF00796B)
                            else -> Color(0xFF1565C0)
                        },
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            BookingLocationRow(
                from = booking.pickupAddress,
                to = booking.destinationAddress,
                language = language
            )

            Spacer(modifier = Modifier.height(10.dp))
            Spacer(modifier = Modifier.height(1.dp).fillMaxWidth().background(Color(0xFFF0F0F0)))
            Spacer(modifier = Modifier.height(10.dp))

            // Action row
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    IconButton(
                        onClick = onCall,
                        modifier = Modifier
                            .size(36.dp)
                            .background(Color(0xFFECEFF1), CircleShape)
                    ) {
                        Icon(Icons.Filled.Phone, contentDescription = "Call", tint = Color(0xFF37474F), modifier = Modifier.size(16.dp))
                    }
                    IconButton(
                        onClick = onChat,
                        modifier = Modifier
                            .size(36.dp)
                            .background(Color(0xFFECEFF1), CircleShape)
                    ) {
                        Icon(Icons.Filled.Chat, contentDescription = "Chat", tint = Color(0xFF37474F), modifier = Modifier.size(16.dp))
                    }
                }

                Button(
                    onClick = onUpdateStatus,
                    colors = ButtonDefaults.buttonColors(containerColor = BloodRed),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 6.dp)
                ) {
                    Icon(Icons.Filled.Edit, contentDescription = null, modifier = Modifier.size(14.dp), tint = Color.White)
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(text = if (isBn) "অবস্থা পরিবর্তন করুন" else "Update Status", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                }
            }
        }
    }
}

@Composable
fun PastTripCard(
    booking: AmbulanceBooking,
    language: AppLanguage,
    onPayCommission: () -> Unit
) {
    val isBn = language == AppLanguage.BAN
    val isCancelled = booking.status == "Cancelled"

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 6.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, LightBorder)
    ) {
        Column(modifier = Modifier.padding(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = booking.patientName,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    color = DarkText
                )
                Surface(
                    color = if (isCancelled) Color(0xFFFFEBEE) else Color(0xFFE8F5E9),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isBn) {
                            if (isCancelled) "বাতিল" else "সম্পন্ন"
                        } else booking.status,
                        fontSize = 10.sp,
                        color = if (isCancelled) Color(0xFFC62828) else Color(0xFF2E7D32),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                    )
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            BookingLocationRow(
                from = booking.pickupAddress,
                to = booking.destinationAddress,
                language = language
            )

            if (!isCancelled) {
                Spacer(modifier = Modifier.height(10.dp))
                Spacer(modifier = Modifier.height(1.dp).fillMaxWidth().background(Color(0xFFF0F0F0)))
                Spacer(modifier = Modifier.height(10.dp))

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text(text = if (isBn) "গৃহীত ভাড়া" else "Fare Earned", fontSize = 11.sp, color = SecondaryText)
                        Text(text = "${booking.fare.toInt()} BDT", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = Color(0xFF2E7D32))
                    }

                    if (booking.isCommissionPaid) {
                        Surface(
                            color = Color(0xFFE8F5E9),
                            shape = RoundedCornerShape(6.dp)
                        ) {
                            Text(
                                text = if (isBn) "কমিশন পরিশোধিত" else "Commission Paid",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF2E7D32),
                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                            )
                        }
                    } else {
                        Button(
                            onClick = onPayCommission,
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFE65100)),
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            val ratePct = if (booking.fare > 0.0) {
                                ((booking.commission / booking.fare) * 100.0).toInt()
                            } else {
                                5
                            }
                            Text(
                                text = if (isBn) "$ratePct% কমিশন পরিশোধ করুন" else "Pay $ratePct% Commission",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color.White
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun BookingLocationRow(from: String, to: String, language: AppLanguage) {
    val isBn = language == AppLanguage.BAN
    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(
                modifier = Modifier
                    .size(6.dp)
                    .background(Color(0xFF2196F3), CircleShape)
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = "${if (isBn) "यात्रा শুরু" else "From"}: $from",
                fontSize = 12.sp,
                color = DarkText,
                maxLines = 1,
                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
            )
        }
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(
                modifier = Modifier
                    .size(6.dp)
                    .background(BloodRed, CircleShape)
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                text = "${if (isBn) "গন্তব্য" else "To"}: $to",
                fontSize = 12.sp,
                color = DarkText,
                maxLines = 1,
                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
fun SupportModalDialog(
    language: AppLanguage,
    viewModel: MainViewModel,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(
                    imageVector = Icons.Default.HeadsetMic,
                    contentDescription = "Support",
                    tint = BloodRed,
                    modifier = Modifier.size(24.dp)
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (language == AppLanguage.BAN) "কাস্টমার সাপোর্ট ও হেল্পডেস্ক" else "Customer Support & Helpdesk",
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold,
                    color = DarkText
                )
            }
        },
        text = {
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    text = if (language == AppLanguage.BAN) "যেকোনো সাহায্য, পেমেন্ট ভেরিফিকেশন বা ট্রানজেকশন স্ক্রিনশটের জন্য আমাদের সাথে যোগাযোগ করুন:" else "Connect with our official support channels below:",
                    fontSize = 12.sp,
                    color = SecondaryText
                )

                // 1. Call
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            onDismiss()
                            try {
                                val intent = Intent(Intent.ACTION_DIAL, Uri.parse("tel:01700000000"))
                                context.startActivity(intent)
                            } catch (e: Exception) {
                                Toast.makeText(context, "Call: 01700000000", Toast.LENGTH_SHORT).show()
                            }
                        },
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F5E9)),
                    border = BorderStroke(1.dp, Color(0xFF2E7D32)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(color = Color(0xFF2E7D32), shape = CircleShape, modifier = Modifier.size(36.dp)) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Default.Call, contentDescription = "Call", tint = Color.White, modifier = Modifier.size(20.dp))
                            }
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text(if (language == AppLanguage.BAN) "Call (সরাসরি কল করুন)" else "Call Support", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color(0xFF1B5E20))
                            Text("01700000000 / 01800000000", fontSize = 11.sp, color = DarkText)
                        }
                    }
                }

                // 2. Live Chat
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            onDismiss()
                            viewModel.startSupportChat()
                        },
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F0FE)),
                    border = BorderStroke(1.dp, Color(0xFF1976D2)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(color = Color(0xFF1976D2), shape = CircleShape, modifier = Modifier.size(36.dp)) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Default.Chat, contentDescription = "Live Chat", tint = Color.White, modifier = Modifier.size(20.dp))
                            }
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text(if (language == AppLanguage.BAN) "Live Chat (লাইভ ইন-অ্যাপ চ্যাট)" else "Live Chat", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color(0xFF0D47A1))
                            Text(if (language == AppLanguage.BAN) "২৪/৭ এডমিন সাপোর্ট চ্যাট রুম" else "24/7 Support Chat Room", fontSize = 11.sp, color = DarkText)
                        }
                    }
                }

                // 3. Email
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            onDismiss()
                            try {
                                val intent = Intent(Intent.ACTION_SENDTO, Uri.parse("mailto:help.alifshen.ltd@gmail.com")).apply {
                                    putExtra(Intent.EXTRA_SUBJECT, "BloodConnect Support Request")
                                }
                                context.startActivity(intent)
                            } catch (e: Exception) {
                                Toast.makeText(context, "help.alifshen.ltd@gmail.com", Toast.LENGTH_LONG).show()
                            }
                        },
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF3E0)),
                    border = BorderStroke(1.dp, Color(0xFFE65100)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(color = Color(0xFFE65100), shape = CircleShape, modifier = Modifier.size(36.dp)) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Default.Email, contentDescription = "Email", tint = Color.White, modifier = Modifier.size(20.dp))
                            }
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text(if (language == AppLanguage.BAN) "Email (অফিশিয়াল ইমেইল)" else "Email Support", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color(0xFFBF360C))
                            Text("help.alifshen.ltd@gmail.com", fontSize = 11.sp, color = DarkText)
                        }
                    }
                }

                // 4. Telegram Group
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            onDismiss()
                            try {
                                val intent = Intent(Intent.ACTION_VIEW, Uri.parse("https://t.me/alifbloodbank"))
                                context.startActivity(intent)
                            } catch (e: Exception) {
                                Toast.makeText(context, "https://t.me/alifbloodbank", Toast.LENGTH_LONG).show()
                            }
                        },
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFE0F7FA)),
                    border = BorderStroke(1.dp, Color(0xFF00838F)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Surface(color = Color(0xFF00838F), shape = CircleShape, modifier = Modifier.size(36.dp)) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Default.Send, contentDescription = "Telegram", tint = Color.White, modifier = Modifier.size(20.dp))
                            }
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text(if (language == AppLanguage.BAN) "Telegram Group (টেলিগ্রাম গ্রুপ)" else "Telegram Group", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color(0xFF006064))
                            Text("t.me/alifbloodbank • অফিসিয়াল চ্যানেল", fontSize = 11.sp, color = DarkText)
                        }
                    }
                }
            }
        },
        confirmButton = {
            TextButton(onClick = onDismiss) {
                Text(if (language == AppLanguage.BAN) "বন্ধ করুন" else "Close", fontWeight = FontWeight.Bold)
            }
        }
    )
}

@Composable
fun PlanPaymentModalDialog(
    planTitle: String,
    planPrice: Double,
    language: AppLanguage,
    viewModel: MainViewModel,
    onDismiss: () -> Unit,
    onPaymentSuccess: (method: String, txnId: String) -> Unit
) {
    var selectedCurrencyTab by remember { mutableStateOf("USD") } // "USD", "USDT", "BDT"
    var selectedUsdOption by remember { mutableStateOf("Google Pay") } // "Google Pay", "Wise", "Payoneer"
    var selectedUsdtNetwork by remember { mutableStateOf("ERC20 (ETH)") } // "TRC20", "ERC20 (ETH)", "BEP20", "Solana", "Polygon"
    var selectedBdtOption by remember { mutableStateOf("bKash") } // "bKash", "Nagad", "Rocket", "Upay"

    var senderInfo by remember { mutableStateOf("") }
    var txnId by remember { mutableStateOf("") }
    var screenshotUri by remember { mutableStateOf<Uri?>(null) }

    val photoPicker = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        if (uri != null) {
            screenshotUri = uri
        }
    }

    val currentUser by viewModel.currentUser.collectAsState()
    val bkashNum by viewModel.bkashNumber.collectAsState()
    val nagadNum by viewModel.nagadNumber.collectAsState()
    val rocketNum by viewModel.rocketNumber.collectAsState()
    val upayNum by viewModel.upayNumber.collectAsState()
    val wiseAccount by viewModel.wiseAccount.collectAsState()
    val payoneerAccount by viewModel.payoneerAccount.collectAsState()
    val usdtAddress by viewModel.usdtWalletAddress.collectAsState()

    val bkashInst by viewModel.bkashInstructions.collectAsState()
    val nagadInst by viewModel.nagadInstructions.collectAsState()
    val rocketInst by viewModel.rocketInstructions.collectAsState()
    val wiseInst by viewModel.wiseInstructions.collectAsState()

    val context = LocalContext.current

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Column {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Payments,
                        contentDescription = null,
                        tint = Color(0xFF2E7D32),
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = if (language == AppLanguage.BAN) "পেমেন্ট মাধ্যম বেছে নিন" else "Select Payment Gateway",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = DarkText
                    )
                }
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = "$planTitle • ৳${planPrice.toInt()} BDT",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color(0xFF2E7D32)
                )
            }
        },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = if (language == AppLanguage.BAN) "পেমেন্ট পদ্ধতি নির্বাচন করুন (Wallet, BDT, USD, USDT):" else "Select Payment Method (Wallet, BDT, USD, USDT):",
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = DarkText
                )

                // 4 MAIN PAYMENT METHOD TABS: WALLET, BDT, USD, USDT
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    listOf(
                        "WALLET" to (if (language == AppLanguage.BAN) "ওয়ালেট" else "Wallet"),
                        "BDT" to "BDT (৳)",
                        "USD" to "USD ($)",
                        "USDT" to "USDT"
                    ).forEach { (key, label) ->
                        val isSelected = selectedCurrencyTab == key
                        Surface(
                            modifier = Modifier
                                .weight(1f)
                                .clickable { selectedCurrencyTab = key },
                            shape = RoundedCornerShape(8.dp),
                            color = if (isSelected) Color(0xFF2E7D32) else Color(0xFFF0F0F0),
                            border = BorderStroke(1.dp, if (isSelected) Color(0xFF1B5E20) else Color.LightGray)
                        ) {
                            Text(
                                text = label,
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isSelected) Color.White else DarkText,
                                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                modifier = Modifier.padding(vertical = 8.dp, horizontal = 2.dp)
                            )
                        }
                    }
                }

                // TAB CONTENT BASED ON CURRENCY/METHOD
                when (selectedCurrencyTab) {
                    "WALLET" -> {
                        val userBalance = currentUser?.walletBalance ?: 0.0
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F5E9)),
                            border = BorderStroke(1.dp, Color(0xFF2E7D32))
                        ) {
                            Column(
                                modifier = Modifier.padding(14.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Icon(Icons.Default.AccountBalanceWallet, contentDescription = null, tint = Color(0xFF2E7D32), modifier = Modifier.size(36.dp))
                                Spacer(modifier = Modifier.height(6.dp))
                                Text(
                                    text = if (language == AppLanguage.BAN) "মাই অ্যাকাউন্ট ওয়ালেট ব্যালেন্স থেকে পেমেন্ট" else "Pay using My Account Wallet Balance",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp,
                                    color = DarkText
                                )
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = if (language == AppLanguage.BAN) "আপনার বর্তমান ওয়ালেট ব্যালেন্স: ৳${userBalance.toInt()}" else "Your Current Wallet Balance: ৳${userBalance.toInt()}",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF1B5E20)
                                )
                                Text(
                                    text = if (language == AppLanguage.BAN) "প্ল্যানের সাবস্ক্রিপশন ফি: ৳${planPrice.toInt()}" else "Plan Subscription Fee: ৳${planPrice.toInt()}",
                                    fontSize = 12.sp,
                                    color = Color.Gray
                                )
                                Spacer(modifier = Modifier.height(10.dp))
                                if (userBalance >= planPrice) {
                                    Button(
                                        onClick = {
                                            val deducted = viewModel.deductWalletBalance(planPrice)
                                            if (deducted) {
                                                Toast.makeText(context, if (language == AppLanguage.BAN) "ওয়ালেট থেকে কেটে নেওয়া হয়েছে!" else "Deducted from wallet balance!", Toast.LENGTH_SHORT).show()
                                                onPaymentSuccess("Wallet Balance", "WALLET_PAY_${System.currentTimeMillis()}")
                                            } else {
                                                Toast.makeText(context, if (language == AppLanguage.BAN) "ব্যালেন্স থেকে কাটতে ব্যর্থ!" else "Failed to deduct from wallet!", Toast.LENGTH_SHORT).show()
                                            }
                                        },
                                        modifier = Modifier.fillMaxWidth().height(42.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        Text(
                                            text = if (language == AppLanguage.BAN) "ওয়ালেট ব্যালেন্স দিয়ে প্ল্যান পরিবর্তন নিশ্চিত করুন (৳${planPrice.toInt()})" else "Confirm Plan Switch with Wallet Balance (৳${planPrice.toInt()})",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                } else {
                                    Text(
                                        text = if (language == AppLanguage.BAN) "আপনার ওয়ালেটে পর্যাপ্ত ব্যালেন্স নেই। প্রয়োজনীয়: ৳${planPrice.toInt()}, বর্তমান: ৳${userBalance.toInt()}। 'মাই একাউন্ট' থেকে ওয়ালেট রিচার্জ করুন।" else "Insufficient Wallet Balance. Required: ৳${planPrice.toInt()}, Available: ৳${userBalance.toInt()}. Please recharge wallet from My Account.",
                                        fontSize = 11.sp,
                                        color = BloodRed,
                                        textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                    )
                                }
                            }
                        }
                    }
                    "USD" -> {
                        // USD GATEWAYS: Google Pay, Wise, Payoneer
                        Text(
                            text = if (language == AppLanguage.BAN) "USD পেমент অপশন নির্বাচন করুন:" else "Select USD Payment Gateway:",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = DarkText
                        )
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            listOf("Google Pay", "Wise", "Payoneer").forEach { option ->
                                val isSelected = selectedUsdOption == option
                                FilterChip(
                                    selected = isSelected,
                                    onClick = { selectedUsdOption = option },
                                    label = { Text(option, fontSize = 11.sp, fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal) },
                                    modifier = Modifier.weight(1f)
                                )
                            }
                        }

                        if (selectedUsdOption == "Google Pay") {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F0FE)),
                                border = BorderStroke(1.dp, Color(0xFF4285F4))
                            ) {
                                Column(
                                    modifier = Modifier.padding(14.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Payment,
                                        contentDescription = null,
                                        tint = Color(0xFF4285F4),
                                        modifier = Modifier.size(36.dp)
                                    )
                                    Spacer(modifier = Modifier.height(6.dp))
                                    Text(
                                        text = "Google Pay & Card Checkout",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp,
                                        color = Color(0xFF1565C0)
                                    )
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = if (language == AppLanguage.BAN) "গুগল পে তে স্ক্রিনশট লাগবে না। সরাসরি পেমেন্ট সম্পন্ন করুন।" else "Google Pay instant checkout (No screenshot mandatory).",
                                        fontSize = 11.sp,
                                        color = DarkText.copy(alpha = 0.8f),
                                        textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                    )
                                    Spacer(modifier = Modifier.height(10.dp))
                                    Button(
                                        onClick = {
                                            val finalTxn = "GPAY_${System.currentTimeMillis()}"
                                            onPaymentSuccess("Google Pay (USD)", finalTxn)
                                        },
                                        modifier = Modifier.fillMaxWidth().height(42.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF4285F4)),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        Text(
                                            text = if (language == AppLanguage.BAN) "Google Pay দিয়ে পেমেন্ট নিশ্চিত করুন" else "Pay with Google Pay ($${(planPrice / 120.0).toInt().coerceAtLeast(5)})",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        } else {
                            val officialAccount = if (selectedUsdOption == "Wise") wiseAccount else payoneerAccount
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFFAFAFA)),
                                border = BorderStroke(1.dp, Color(0xFFE0E0E0))
                            ) {
                                Column(modifier = Modifier.padding(12.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = "$selectedUsdOption Official Account:",
                                                fontSize = 11.sp,
                                                color = Color.Gray
                                            )
                                            Text(
                                                text = officialAccount.ifBlank { "payoneer.global@alifbd.com" },
                                                fontSize = 13.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = DarkText
                                            )
                                        }
                                        TextButton(
                                            onClick = {
                                                val clipboard = context.getSystemService(android.content.Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                                                val clip = android.content.ClipData.newPlainText("Payment Account", officialAccount)
                                                clipboard.setPrimaryClip(clip)
                                                Toast.makeText(context, if (language == AppLanguage.BAN) "অ্যাকাউন্ট কপি হয়েছে!" else "Account Copied!", Toast.LENGTH_SHORT).show()
                                            }
                                        ) {
                                            Text(if (language == AppLanguage.BAN) "কপি" else "Copy", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(8.dp))

                                    OutlinedTextField(
                                        value = senderInfo,
                                        onValueChange = { senderInfo = it },
                                        label = { Text(if (language == AppLanguage.BAN) "আপনার $selectedUsdOption ইমেইল/আইডি" else "Your $selectedUsdOption Email/ID") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true
                                    )

                                    Spacer(modifier = Modifier.height(6.dp))

                                    OutlinedTextField(
                                        value = txnId,
                                        onValueChange = { txnId = it },
                                        label = { Text(if (language == AppLanguage.BAN) "ট্রানজেকশন আইডি (Txn ID) *" else "Transaction ID (Txn ID) *") },
                                        modifier = Modifier.fillMaxWidth(),
                                        singleLine = true
                                    )

                                    Spacer(modifier = Modifier.height(8.dp))

                                    Text(
                                        text = if (language == AppLanguage.BAN) "পেমেন্ট স্ক্রিনশট (Payment Screenshot) *" else "Payment Screenshot *",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = DarkText
                                    )

                                    Spacer(modifier = Modifier.height(4.dp))

                                    OutlinedButton(
                                        onClick = { photoPicker.launch("image/*") },
                                        modifier = Modifier.fillMaxWidth().height(42.dp),
                                        shape = RoundedCornerShape(8.dp),
                                        colors = ButtonDefaults.outlinedButtonColors(
                                            containerColor = if (screenshotUri != null) Color(0xFFE8F5E9) else Color.White
                                        ),
                                        border = BorderStroke(1.dp, if (screenshotUri != null) Color(0xFF2E7D32) else Color.Gray)
                                    ) {
                                        Icon(
                                            imageVector = if (screenshotUri != null) Icons.Default.CheckCircle else Icons.Default.AddPhotoAlternate,
                                            contentDescription = "Upload Screenshot",
                                            tint = if (screenshotUri != null) Color(0xFF2E7D32) else Color.Gray,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (screenshotUri != null) {
                                                if (language == AppLanguage.BAN) "✓ স্ক্রিনশট যুক্ত হয়েছে" else "✓ Screenshot Attached"
                                            } else {
                                                if (language == AppLanguage.BAN) "পেমেন্ট স্ক্রিনশট সিলেক্ট করুন" else "Select Payment Screenshot"
                                            },
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.SemiBold,
                                            color = if (screenshotUri != null) Color(0xFF1B5E20) else DarkText
                                        )
                                    }

                                    if (screenshotUri != null) {
                                        Spacer(modifier = Modifier.height(6.dp))
                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(100.dp)
                                                .clip(RoundedCornerShape(8.dp)),
                                            border = BorderStroke(1.dp, Color(0xFF81C784))
                                        ) {
                                            Box(modifier = Modifier.fillMaxSize()) {
                                                AsyncImage(
                                                    model = screenshotUri,
                                                    contentDescription = "Payment Screenshot",
                                                    modifier = Modifier.fillMaxSize(),
                                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                                )
                                                Surface(
                                                    color = Color.Black.copy(alpha = 0.6f),
                                                    shape = RoundedCornerShape(bottomStart = 8.dp),
                                                    modifier = Modifier.align(Alignment.TopEnd)
                                                ) {
                                                    IconButton(
                                                        onClick = { screenshotUri = null },
                                                        modifier = Modifier.size(28.dp)
                                                    ) {
                                                        Icon(Icons.Default.Close, contentDescription = "Remove", tint = Color.White, modifier = Modifier.size(16.dp))
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    Spacer(modifier = Modifier.height(10.dp))

                                    Button(
                                        onClick = {
                                            if (txnId.isBlank()) {
                                                Toast.makeText(context, if (language == AppLanguage.BAN) "অনুগ্রহ করে ট্রানজেকশন আইডি (Txn ID) প্রদান করুন" else "Please enter Transaction ID", Toast.LENGTH_SHORT).show()
                                                return@Button
                                            }
                                            val finalTxn = if (screenshotUri != null) "$txnId | Screenshot: Attached" else txnId
                                            onPaymentSuccess("$selectedUsdOption (USD)", finalTxn)
                                        },
                                        modifier = Modifier.fillMaxWidth().height(42.dp),
                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        Icon(Icons.Default.CheckCircle, contentDescription = null, modifier = Modifier.size(16.dp))
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (language == AppLanguage.BAN) "পেমেন্ট নিশ্চিত করুন ($${(planPrice / 120.0).toInt().coerceAtLeast(5)})" else "Confirm Payment ($${(planPrice / 120.0).toInt().coerceAtLeast(5)})",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }

                    "USDT" -> {
                        Text(
                            text = if (language == AppLanguage.BAN) "USDT নেটওয়ার্ক সিলেক্ট করুন (ETH, TRC20, BSC, Solana, Polygon):" else "Select USDT Network (ETH, TRC20, BSC, Solana, Polygon):",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = DarkText
                        )

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .horizontalScroll(rememberScrollState()),
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            listOf("ERC20 (ETH)", "TRC20 (Tron)", "BEP20 (BNB)", "Solana (SOL)", "Polygon").forEach { net ->
                                val isSelected = selectedUsdtNetwork == net
