                }
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Option 1: Free Plan
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(1.dp, Color.LightGray, RoundedCornerShape(12.dp)),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF5F5F5)),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Column(modifier = Modifier.padding(12.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (language == AppLanguage.BAN) "১. ফ্রি ডাক্তার প্ল্যান" else "1. Free Doctor Plan",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = DarkText
                                )
                                Surface(
                                    color = Color.Gray,
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text(
                                        text = if (language == AppLanguage.BAN) "৳০ / স্থায়ী (মেয়াদহীন)" else "Free / Permanent",
                                        color = Color.White,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(if (language == AppLanguage.BAN) "✓ বিনামূল্যে চেম্বার লিস্টিং (স্থায়ী / নো এক্সপায়ারি)" else "✓ Free doctor chamber listing (Permanent / Lifetime)", fontSize = 11.sp, color = DarkText)
                            Text(if (language == AppLanguage.BAN) "✓ অনলাইন সিরিয়াল বুকিং ও হেল্পডেস্ক চ্যাট সেবা" else "✓ Online serial booking & helpdesk chat service", fontSize = 11.sp, color = DarkText)
                            Text(if (language == AppLanguage.BAN) "✖ সরাসরি ফোন নম্বর ও ডাইরেক্ট কল ফিচার বন্ধ" else "✖ Direct mobile call feature disabled", fontSize = 11.sp, color = Color.Gray)
                            Spacer(modifier = Modifier.height(10.dp))
                            Button(
                                onClick = {
                                    viewModel.updateDoctorPlan("", "Free")
                                    Toast.makeText(context, if (language == AppLanguage.BAN) "ফ্রি প্ল্যান সফলভাবে সক্রিয় হয়েছে!" else "Free plan activated successfully!", Toast.LENGTH_SHORT).show()
                                    showPlanSelectionModal = false
                                },
                                modifier = Modifier.fillMaxWidth().height(38.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = Color.DarkGray),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Text(if (language == AppLanguage.BAN) "ফ্রি প্ল্যান সক্রিয় করুন" else "Activate Free Plan", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Option 2: Advance Plan
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .border(1.5.dp, Color(0xFF8E24AA), RoundedCornerShape(12.dp)),
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF3E5F5)),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Column(modifier = Modifier.padding(12.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (language == AppLanguage.BAN) "২. অ্যাডভান্স প্রিমিয়াম প্ল্যান" else "2. Advance Premium Plan",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = Color(0xFF6A1B9A)
                                )
                                Surface(
                                    color = Color(0xFF8E24AA),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text(
                                        text = if (language == AppLanguage.BAN) "৳৪৯৯ / আনলিমিটেড লাইফটাইম" else "৳499 / Lifetime",
                                        color = Color.White,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(if (language == AppLanguage.BAN) "✓ সরাসরি মোবাইল নম্বর ও ডায়রেক্ট কল বাটন অন" else "✓ Direct mobile number & direct call button enabled", fontSize = 11.sp, color = DarkText, fontWeight = FontWeight.Bold)
                            Text(if (language == AppLanguage.BAN) "✓ সার্চ রেজাল্টে গোল্ডেন প্রিমিয়াম ব্যাজ ও সবার উপরে টপ পজিশন" else "✓ Golden Premium badge & top position in specialty search", fontSize = 11.sp, color = DarkText)
                            Text(if (language == AppLanguage.BAN) "✓ গুগল প্লে ও ওয়াইজ ইন্টারন্যাশনাল পেমেন্ট সাপোর্টেড" else "✓ Google Play & Wise international payment supported", fontSize = 11.sp, color = DarkText)
                            
                            Spacer(modifier = Modifier.height(12.dp))
                            HorizontalDivider(color = Color(0xFFE1BEE7))
                            Spacer(modifier = Modifier.height(8.dp))

                            Text(
                                text = if (language == AppLanguage.BAN) "পেমেন্ট মাধ্যম বেছে নিন:" else "Select Payment Method:",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF6A1B9A)
                            )
                            Spacer(modifier = Modifier.height(6.dp))

                            Button(
                                onClick = { showDoctorPaymentSheet = true },
                                modifier = Modifier.fillMaxWidth().height(42.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF8E24AA)),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Icon(Icons.Filled.Payments, contentDescription = null, modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text(
                                    text = if (language == AppLanguage.BAN) "পে করুন (৳৪৯৯)" else "Pay (৳499)",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }
                }
            },
            confirmButton = {},
            dismissButton = {
                TextButton(onClick = { showPlanSelectionModal = false }) {
                    Text(if (language == AppLanguage.BAN) "বন্ধ করুন" else "Close")
                }
            }
        )
    }

    if (showDoctorPaymentSheet) {
        PlanPaymentModalDialog(
            planTitle = if (language == AppLanguage.BAN) "ডাক্তার অ্যাডভান্স প্ল্যান" else "Doctor Advance Plan",
            planPrice = 499.0,
            language = language,
            viewModel = viewModel,
            onDismiss = { showDoctorPaymentSheet = false },
            onPaymentSuccess = { method, txnId ->
                viewModel.updateDoctorPlan("", "Advance (Monthly)", paymentMethod = method, txnId = txnId)
                Toast.makeText(context, if (language == AppLanguage.BAN) "পেমেন্ট সফল! ডাক্তার অ্যাডভান্স ফিচার সক্রিয় হয়েছে।" else "Payment Successful! Doctor Advance Plan activated.", Toast.LENGTH_LONG).show()
                showDoctorPaymentSheet = false
                showPlanSelectionModal = false
            }
        )
    }

    // Modal 3: Doctor Chat Modal
    selectedDoctorForChat?.let { doc ->
        AlertDialog(
            onDismissRequest = { selectedDoctorForChat = null },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Filled.Chat, contentDescription = "Chat", tint = Color(0xFF8E24AA))
                    Spacer(modifier = Modifier.width(8.dp))
                    Column {
                        Text(doc.name, fontSize = 15.sp, fontWeight = FontWeight.Bold)
                        Text("${doc.titleDegree} - ${doc.specialty}", fontSize = 11.sp, color = SecondaryText)
                    }
                }
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF3E5F5)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(10.dp)) {
                            Text(
                                text = if (language == AppLanguage.BAN) "ডাক্তার অ্যাসিস্ট্যান্ট চ্যাট:" else "Doctor Helpdesk:",
                                fontWeight = FontWeight.Bold,
                                fontSize = 11.sp,
                                color = Color(0xFF8E24AA)
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (language == AppLanguage.BAN) "রোগীর স্বাস্থ্যবিষয়ক প্রাথমিক তথ্য বা পরামর্শ অনুসন্ধানের জন্য বার্তা লিখুন। বিজ্ঞ ডাক্তার/সহকারী দ্রুত উত্তর প্রদান করবেন।"
                                else "Send primary inquiry message. Doctor/assistant will respond promptly.",
                                fontSize = 12.sp,
                                color = DarkText
                            )
                        }
                    }

                    OutlinedTextField(
                        value = docChatMessage,
                        onValueChange = { docChatMessage = it },
                        placeholder = { Text(if (language == AppLanguage.BAN) "আপনার স্বাস্থ্য বিষয়ক প্রশ্ন লিখুন..." else "Write health question...", fontSize = 12.sp) },
                        modifier = Modifier.fillMaxWidth(),
                        maxLines = 3
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (docChatMessage.isBlank()) {
                            Toast.makeText(context, "Please enter a message", Toast.LENGTH_SHORT).show()
                            return@Button
                        }
                        Toast.makeText(context, if (language == AppLanguage.BAN) "বার্তা পাঠানো হয়েছে! ডাক্তার দ্রুত উত্তর দিবেন।" else "Message sent! Doctor will respond soon.", Toast.LENGTH_LONG).show()
                        docChatMessage = ""
                        selectedDoctorForChat = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF8E24AA))
                ) {
                    Text(if (language == AppLanguage.BAN) "বার্তা পাঠান" else "Send Message")
                }
            },
            dismissButton = {
                TextButton(onClick = { selectedDoctorForChat = null }) {
                    Text(if (language == AppLanguage.BAN) "বন্ধ করুন" else "Close")
                }
            }
        )
    }

    // Modal 4: Doctor Serial Booking Modal
    selectedDoctorForBooking?.let { doc ->
        AlertDialog(
            onDismissRequest = { selectedDoctorForBooking = null },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Filled.CalendarMonth, contentDescription = "Book", tint = Color(0xFF00897B))
                    Spacer(modifier = Modifier.width(8.dp))
                    Column {
                        Text(if (language == AppLanguage.BAN) "ডাক্তার অ্যাপয়েন্টমেন্ট বুকিং" else "Doctor Serial Booking", fontSize = 15.sp, fontWeight = FontWeight.Bold)
                        Text("${doc.name} (${doc.specialty})", fontSize = 11.sp, color = SecondaryText)
                    }
                }
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFE0F2F1)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(8.dp)) {
                            Text("${if (language == AppLanguage.BAN) "চেম্বার: " else "Chamber: "}${doc.hospitalName}, ${doc.district}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = DarkText)
                            Text("${if (language == AppLanguage.BAN) "সময়: " else "Hours: "}${doc.visitingHours} | ${if (language == AppLanguage.BAN) "ফি: " else "Fee: "}${doc.consultationFee}", fontSize = 11.sp, color = SecondaryText)
                        }
                    }

                    OutlinedTextField(
                        value = docBookPatientName,
                        onValueChange = { docBookPatientName = it },
                        label = { Text(if (language == AppLanguage.BAN) "রোগীর নাম (Patient Name) *" else "Patient Name *") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )

                    OutlinedTextField(
                        value = docBookPhone,
                        onValueChange = { docBookPhone = it },
                        label = { Text(if (language == AppLanguage.BAN) "মোবাইল নম্বর (Contact Mobile) *" else "Contact Mobile *") },
                        modifier = Modifier.fillMaxWidth(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        singleLine = true
                    )

                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        OutlinedTextField(
                            value = docBookAge,
                            onValueChange = { docBookAge = it },
                            label = { Text(if (language == AppLanguage.BAN) "বয়স (Age)" else "Age") },
                            modifier = Modifier.weight(1f),
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            singleLine = true
                        )
                        OutlinedTextField(
                            value = docBookDate,
                            onValueChange = { docBookDate = it },
                            label = { Text(if (language == AppLanguage.BAN) "তারিখ (Date)" else "Date") },
                            modifier = Modifier.weight(1f),
                            singleLine = true
                        )
                    }

                    OutlinedTextField(
                        value = docBookProblem,
                        onValueChange = { docBookProblem = it },
                        label = { Text(if (language == AppLanguage.BAN) "রোগের বিবরণ (Symptoms/Problem)" else "Symptoms/Problem") },
                        modifier = Modifier.fillMaxWidth(),
                        maxLines = 2
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (docBookPatientName.isBlank() || docBookPhone.isBlank()) {
                            Toast.makeText(context, "Please enter patient name and phone", Toast.LENGTH_SHORT).show()
                            return@Button
                        }
                        val currentUsr = viewModel.currentUser.value
                        viewModel.submitServiceBooking(
                            com.example.data.ServiceBooking(
                                id = "doc_${System.currentTimeMillis()}",
                                bookingType = "Doctor",
                                userPhone = currentUsr?.phone ?: docBookPhone,
                                userName = currentUsr?.name ?: docBookPatientName,
                                providerName = "${doc.name} (${doc.specialty})",
                                providerPhone = doc.phone,
                                serviceName = "Doctor Serial - ${doc.specialty}",
                                bookingDate = docBookDate.ifBlank { "Immediate" },
                                patientName = docBookPatientName,
                                patientPhone = docBookPhone,
                                patientAge = docBookAge,
                                district = doc.district,
                                upazila = doc.upazila,
                                status = "Pending",
                                notes = "Problem: $docBookProblem, Chamber: ${doc.chamberAddress}",
                                timestamp = System.currentTimeMillis()
                            )
                        )
                        Toast.makeText(context, if (language == AppLanguage.BAN) "ডাক্তারের অ্যাপয়েন্টমেন্ট বুকিং সফলভাবে সম্পন্ন হয়েছে! 'মাই বুকিং' এ দেখা যাবে।" else "Doctor appointment booking confirmed successfully!", Toast.LENGTH_LONG).show()
                        docBookPatientName = ""
                        docBookPhone = ""
                        docBookAge = ""
                        docBookDate = ""
                        docBookProblem = ""
                        selectedDoctorForBooking = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF00897B))
                ) {
                    Text(if (language == AppLanguage.BAN) "সিরিয়াল নিশ্চিত করুন" else "Confirm Serial")
                }
            },
            dismissButton = {
                TextButton(onClick = { selectedDoctorForBooking = null }) {
                    Text(if (language == AppLanguage.BAN) "বাতিল" else "Cancel")
                }
            }
        )
    }
}

// --- 28. ADVERTISER / COMPANY TOP BANNER PORTAL ---
@Composable
fun AdvertiserPortalScreen(viewModel: MainViewModel) {
    val context = LocalContext.current
    val language by viewModel.language.collectAsState()
    val currentAdvertiser by viewModel.currentAdvertiser.collectAsState()
    val customAdConfigs by viewModel.customAdConfigs.collectAsState()
    val companySubscriptions by viewModel.companySubscriptions.collectAsState()

    var authTabIsRegister by remember { mutableStateOf(true) } // true for Register, false for Login

    // Advertiser Registration States
    var compNameInput by remember { mutableStateOf("") }
    var compEmailInput by remember { mutableStateOf("") }
    var compPhoneInput by remember { mutableStateOf("") }
    var compPassInput by remember { mutableStateOf("") }
    var compTypeInput by remember { mutableStateOf("Healthcare") }
    var compWebsiteInput by remember { mutableStateOf("") }

    // Advertiser Login States
    var loginIdentifierInput by remember { mutableStateOf("") }
    var loginPassInput by remember { mutableStateOf("") }

    // Ad Creation & Subscription States
    var selectedPlanType by remember { mutableStateOf("Weekly (৳500)") } // "Weekly (৳500)", "Monthly (৳1800)"
    var adTitleInput by remember { mutableStateOf("") }
    var isVideoAd by remember { mutableStateOf(false) }
    var bannerMediaUrlInput by remember { mutableStateOf("") }
    var targetUrlInput by remember { mutableStateOf("") }
