                                OutlinedTextField(
                                    value = compWebsiteInput,
                                    onValueChange = { compWebsiteInput = it },
                                    label = { Text("ওয়েবসাইট/লিংক (Website)") },
                                    modifier = Modifier.weight(1f),
                                    shape = RoundedCornerShape(10.dp)
